-- Caemora Inventory: complete database setup. Generated by scripts/build-setup-sql.sh; do not edit by hand.
-- Paste into Supabase → SQL Editor → New query, and Run. Safe only on a new, empty project.

-- ===== supabase/migrations/20261121000001_schema.sql
-- Caemora inventory: core schema
-- Money is stored as numeric with an explicit currency on every row, so ₹ and £ are never summed together.

create extension if not exists pgcrypto;

create type user_role       as enum ('admin', 'data_entry', 'viewer');
create type currency_code   as enum ('INR', 'GBP', 'USD', 'CNY');
create type sales_channel   as enum ('FBA', 'FBM', 'EBAY', 'ONBUY', 'SHOPIFY', 'OTHER');
create type period_status   as enum ('open', 'settled');
create type shipment_status as enum ('in_transit', 'received', 'received_partial', 'lost', 'cancelled');
create type payment_kind    as enum ('opening', 'closing', 'other');
create type flag_status     as enum ('open', 'acknowledged', 'resolved');
create type flag_severity   as enum ('info', 'warning', 'critical');
create type vendor_kind     as enum ('india_partner', 'supplier', 'alibaba', 'other');
create type line_category   as enum ('stock', 'consumable');

-- ---------------------------------------------------------------- reference data

create table companies (
  code        text primary key,                 -- CMR, ARC, GOE, YD, ALS, GEN, GOA
  name        text not null,
  aliases     text[] not null default '{}',     -- spellings seen in the old sheet, lower-case
  notes       text,
  active      boolean not null default true
);

create table profiles (
  id          uuid primary key references auth.users (id) on delete cascade,
  full_name   text not null,
  email       text,
  role        user_role not null default 'data_entry',
  active      boolean not null default true,
  created_at  timestamptz not null default now()
);

create table vendors (
  id               bigint generated always as identity primary key,
  name             text not null unique,
  kind             vendor_kind not null default 'supplier',
  country          char(2),
  default_currency currency_code not null default 'INR',
  aliases          text[] not null default '{}',
  notes            text,
  active           boolean not null default true
);

create table settings (
  key         text primary key,
  value       jsonb not null,
  description text
);

-- ---------------------------------------------------------------- products

create table products (
  id                       bigint generated always as identity primary key,
  name                     text not null,
  category                 line_category not null default 'stock',
  -- rate card: the agreed courier charge per unit
  agreed_courier_per_unit  numeric(12, 4),
  agreed_courier_currency  currency_code not null default 'INR',
  agreed_courier_from      date,                       -- rate card applies to purchases from this month
  agreed_unit_price        numeric(12, 4),
  agreed_price_currency    currency_code not null default 'INR',
  notes                    text,
  active                   boolean not null default true,
  import_ref               text,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now()
);
create index products_name_idx on products (lower(name));

-- A product as sold by one company on one channel. FNSKUs are per seller account.
create table listings (
  id            bigint generated always as identity primary key,
  product_id    bigint not null references products (id) on delete cascade,
  company_code  text not null references companies (code),
  channel       sales_channel not null default 'FBA',
  asin          text,
  fnsku         text,
  sku           text,
  active        boolean not null default true,
  import_ref    text,
  created_at    timestamptz not null default now()
);
create unique index listings_company_fnsku_uq on listings (company_code, fnsku) where fnsku is not null;
create index listings_asin_idx on listings (asin);

-- ---------------------------------------------------------------- periods

create table periods (
  month       date primary key check (extract(day from month) = 1),
  status      period_status not null default 'open',
  settled_at  timestamptz,
  settled_by  uuid references auth.users (id),
  notes       text
);

create table fx_rates (
  month        date primary key references periods (month),
  inr_per_gbp  numeric(10, 4) not null check (inr_per_gbp > 0),
  source       text not null default 'manual',   -- 'payments' = weighted from that month's Wise payments
  updated_at   timestamptz not null default now()
);

-- ---------------------------------------------------------------- shipments & purchases

create table shipments (
  id                  bigint generated always as identity primary key,
  period_month        date not null references periods (month),
  company_code        text references companies (code),
  channel             sales_channel,
  box_no              text,
  amazon_shipment_id  text,
  uk_shipment_id      text,
  created_on          date,
  courier             text,
  tracking_no         text,
  status              shipment_status not null default 'in_transit',
  received_on         date,
  received_by         text,
  notes               text,
  import_ref          text,
  created_by          uuid references auth.users (id) default auth.uid(),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);
create index shipments_period_idx on shipments (period_month);
create index shipments_tracking_idx on shipments (tracking_no);
create index shipments_amz_idx on shipments (amazon_shipment_id);

create table purchase_lines (
  id                bigint generated always as identity primary key,
  period_month      date not null references periods (month),
  shipment_id       bigint references shipments (id) on delete set null,
  product_id        bigint not null references products (id),
  listing_id        bigint references listings (id),
  company_code      text not null references companies (code),
  vendor_id         bigint not null references vendors (id),
  category          line_category not null default 'stock',
  description       text,                      -- product text as typed / imported
  qty               integer not null check (qty >= 0),
  unit_price        numeric(12, 4),            -- null = blank price (flagged)
  currency          currency_code not null default 'INR',
  courier_per_unit  numeric(12, 4) not null default 0,
  courier_total     numeric(14, 4) generated always as (courier_per_unit * qty) stored,
  goods_total       numeric(14, 4) generated always as (coalesce(unit_price, 0) * qty) stored,
  line_total        numeric(14, 4) generated always as ((coalesce(unit_price, 0) + courier_per_unit) * qty) stored,
  invoice_no        text,
  invoice_date      date,
  defective_qty     integer not null default 0 check (defective_qty >= 0),
  short_qty         integer not null default 0 check (short_qty >= 0),
  received_qty      integer generated always as (qty - defective_qty - short_qty) stored,
  checked_by        text,
  remarks           text,
  remarks_2         text,
  amazon_case_id    text,
  reimbursement_id  text,
  reimbursed_gbp    numeric(12, 2),
  import_ref        text,
  created_by        uuid references auth.users (id) default auth.uid(),
  created_at        timestamptz not null default now(),
  updated_by        uuid references auth.users (id),
  updated_at        timestamptz not null default now()
);
create index purchase_lines_period_idx on purchase_lines (period_month, company_code);
create index purchase_lines_product_idx on purchase_lines (product_id, period_month);
create index purchase_lines_shipment_idx on purchase_lines (shipment_id);

-- ---------------------------------------------------------------- money

create table payments (
  id             bigint generated always as identity primary key,
  period_month   date not null references periods (month),
  company_code   text not null references companies (code),
  vendor_id      bigint not null references vendors (id),
  kind           payment_kind not null default 'other',
  amount         numeric(14, 2) not null,        -- in `currency`
  currency       currency_code not null default 'INR',
  amount_gbp     numeric(14, 2),                 -- what left the UK account
  fx_rate        numeric(10, 4) generated always as (
                   case when currency = 'INR' and amount_gbp > 0 then round(amount / amount_gbp, 4) end) stored,
  paid_on        date,
  method         text,                           -- Wise, Revolut, Amex, Apple Pay...
  paid_from      text,                           -- account the money came from, as written
  paid_from_company text references companies (code),  -- whose bank account paid; null = personal/other account
  reference      text,                           -- Wise transfer no.
  confirmed      boolean not null default true,  -- false = imported "closing" row with no date/method
  notes          text,
  import_ref     text,
  created_by     uuid references auth.users (id) default auth.uid(),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index payments_period_idx on payments (period_month, company_code);

create table credit_notes (
  id                bigint generated always as identity primary key,
  period_month      date not null references periods (month),   -- month it is deducted in
  relates_to_month  date references periods (month),
  company_code      text references companies (code),               -- null = applies to the vendor overall
  vendor_id         bigint not null references vendors (id),
  amount            numeric(14, 2) not null check (amount > 0),  -- positive = reduces balance due
  currency          currency_code not null default 'INR',
  reason            text not null,
  purchase_line_id  bigint references purchase_lines (id) on delete set null,
  import_ref        text,
  created_by        uuid references auth.users (id) default auth.uid(),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

-- ---------------------------------------------------------------- flags & audit

create table flags (
  id               bigint generated always as identity primary key,
  rule             text not null,
  severity         flag_severity not null default 'warning',
  entity_type      text not null,               -- purchase_line, shipment, payment, period
  entity_id        bigint not null,
  period_month     date,
  company_code     text,
  message          text not null,
  details          jsonb not null default '{}',
  status           flag_status not null default 'open',
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  resolved_by      uuid references auth.users (id),
  resolved_at      timestamptz,
  resolution_note  text
);
-- one live flag per rule per record (settled-month edits are an event log, so they repeat)
create unique index flags_rule_entity_uq on flags (rule, entity_type, entity_id) where rule <> 'settled_month_edit';
create index flags_status_idx on flags (status, period_month);

create table audit_log (
  id            bigint generated always as identity primary key,
  table_name    text not null,
  row_key       text,                            -- id, or month/key for tables keyed that way
  action        text not null,                   -- INSERT / UPDATE / DELETE
  old_data      jsonb,
  new_data      jsonb,
  period_month  date,
  reason        text,
  changed_by    uuid,
  changed_at    timestamptz not null default now()
);
create index audit_log_row_idx on audit_log (table_name, row_key);

-- ===== supabase/migrations/20261121000002_security.sql
-- Roles, settled-month lock, audit log and row-level security.

-- ---------------------------------------------------------------- role helpers

create function app_role() returns user_role
language sql stable security definer set search_path = public as $$
  select role from profiles where id = auth.uid() and active
$$;

create function is_active_user() returns boolean language sql stable as $$ select app_role() is not null $$;
create function is_admin()       returns boolean language sql stable as $$ select coalesce(app_role() = 'admin', false) $$;
create function is_staff()       returns boolean language sql stable as $$ select coalesce(app_role() in ('admin', 'data_entry'), false) $$;
create function can_view_money() returns boolean language sql stable as $$ select coalesce(app_role() in ('admin', 'viewer'), false) $$;

-- Direct database connections (the importer, migrations, scheduled jobs) have no JWT user.
create function is_system() returns boolean language sql stable as $$
  select auth.uid() is null and current_user not in ('anon', 'authenticated')
$$;

create function is_importing() returns boolean language sql stable as $$
  select coalesce(current_setting('app.importing', true), '') = 'on' and is_system()
$$;

create function edit_reason() returns text language sql stable as $$
  select nullif(trim(coalesce(current_setting('app.edit_reason', true), '')), '')
$$;

-- New sign-ups get an inactive data-entry profile; an admin activates them and sets the role.
create function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into profiles (id, full_name, email, role, active)
  values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', split_part(new.email, '@', 1)), new.email, 'data_entry', false)
  on conflict (id) do nothing;
  return new;
end $$;

create trigger on_auth_user_created after insert on auth.users
  for each row execute function handle_new_user();

-- Logins created before this setup ran get an (inactive) profile too.
insert into profiles (id, full_name, email, role, active)
select id, coalesce(raw_user_meta_data ->> 'full_name', split_part(email, '@', 1)), email, 'data_entry', false
  from auth.users
on conflict (id) do nothing;

-- ---------------------------------------------------------------- periods

-- Normalise period_month to the 1st and create the period if it is new.
create function ensure_period() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.period_month := date_trunc('month', new.period_month)::date;
  insert into periods (month) values (new.period_month) on conflict do nothing;
  return new;
end $$;

-- Columns about receiving goods, which may change after a month is settled.
create function receipt_columns(p_table text) returns text[] language sql immutable as $$
  select case p_table
    when 'shipments' then array['status', 'received_on', 'received_by', 'tracking_no', 'courier', 'notes', 'updated_at']
    -- generated totals are listed too: they are not yet computed in a BEFORE trigger, and follow from the other columns
    when 'purchase_lines' then array['defective_qty', 'short_qty', 'received_qty', 'checked_by', 'remarks', 'remarks_2',
                                     'amazon_case_id', 'reimbursement_id', 'reimbursed_gbp', 'updated_at', 'updated_by',
                                     'courier_total', 'goods_total', 'line_total']
    else array[]::text[] end
$$;

-- Block changes to settled months. Data entry: always blocked. Admin: allowed with a reason, and flagged.
create function enforce_period_lock() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  rec       jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  m_old     date  := case when tg_op <> 'INSERT' then old.period_month end;
  m_new     date  := case when tg_op <> 'DELETE' then new.period_month end;
  m_settled date;
  reason    text  := edit_reason();
begin
  select month into m_settled from periods
   where month in (m_old, m_new) and status = 'settled' order by month limit 1;
  if m_settled is null then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  -- Receiving goods is not a money change: shipments and receipt details stay editable after a month is settled.
  if tg_op = 'UPDATE' and m_old = m_new and is_staff() then
    if (to_jsonb(new) - receipt_columns(tg_table_name)) = (to_jsonb(old) - receipt_columns(tg_table_name)) then
      return new;
    end if;
  end if;

  if is_system() and coalesce(current_setting('app.bypass_lock', true), '') = 'on' then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if not is_admin() then
    raise exception '% is settled and cannot be changed. Ask an admin.', to_char(m_settled, 'FMMonth YYYY')
      using errcode = 'P0001';
  end if;

  if reason is null then
    raise exception 'A reason is required to change settled month %.', to_char(m_settled, 'FMMonth YYYY')
      using errcode = 'P0001';
  end if;

  insert into flags (rule, severity, entity_type, entity_id, period_month, company_code, message, details)
  values ('settled_month_edit', 'critical', tg_table_name, (rec ->> 'id')::bigint, m_settled, rec ->> 'company_code',
          format('%s on %s in settled month %s: %s', initcap(lower(tg_op)), replace(tg_table_name, '_', ' '),
                 to_char(m_settled, 'FMMonth YYYY'), reason),
          jsonb_build_object('reason', reason, 'by', auth.uid(), 'op', tg_op));

  return case when tg_op = 'DELETE' then old else new end;
end $$;

create function touch_updated() returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  if tg_table_name = 'purchase_lines' then new.updated_by := auth.uid(); end if;
  return new;
end $$;

-- ---------------------------------------------------------------- audit

create function write_audit() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  rec jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
begin
  if is_importing() then return null; end if;
  insert into audit_log (table_name, row_key, action, old_data, new_data, period_month, reason, changed_by)
  values (tg_table_name,
          coalesce(rec ->> 'id', rec ->> 'month', rec ->> 'key', rec ->> 'code'),
          tg_op,
          case when tg_op <> 'INSERT' then to_jsonb(old) end,
          case when tg_op <> 'DELETE' then to_jsonb(new) end,
          case when tg_table_name = 'settings' then null
               else coalesce((rec ->> 'period_month')::date, (rec ->> 'month')::date) end,
          edit_reason(),
          auth.uid());
  return null;
end $$;

-- ---------------------------------------------------------------- rate card protection

create function protect_rate_card() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if is_admin() or is_system() then return new; end if;
  if tg_op = 'INSERT' then
    new.agreed_courier_per_unit := null;
    new.agreed_courier_from := null;
    new.agreed_unit_price := null;
  elsif (new.agreed_courier_per_unit, new.agreed_courier_currency, new.agreed_courier_from, new.agreed_unit_price, new.agreed_price_currency)
        is distinct from
        (old.agreed_courier_per_unit, old.agreed_courier_currency, old.agreed_courier_from, old.agreed_unit_price, old.agreed_price_currency) then
    raise exception 'Only an admin can change the agreed rate card.' using errcode = 'P0001';
  end if;
  return new;
end $$;

create trigger products_rate_card before insert or update on products
  for each row execute function protect_rate_card();

-- ---------------------------------------------------------------- attach triggers

do $$
declare t text;
begin
  foreach t in array array['shipments', 'purchase_lines', 'payments', 'credit_notes'] loop
    execute format('create trigger a_ensure_period before insert or update of period_month on %I
                    for each row execute function ensure_period()', t);
    execute format('create trigger b_period_lock before insert or update or delete on %I
                    for each row execute function enforce_period_lock()', t);
    execute format('create trigger c_touch before update on %I
                    for each row execute function touch_updated()', t);
  end loop;

  foreach t in array array['shipments', 'purchase_lines', 'payments', 'credit_notes',
                           'products', 'listings', 'periods', 'profiles', 'fx_rates', 'settings'] loop
    execute format('create trigger z_audit after insert or update or delete on %I
                    for each row execute function write_audit()', t);
  end loop;
end $$;

create trigger c_touch before update on products for each row execute function touch_updated();

-- ---------------------------------------------------------------- admin RPCs

create function settle_month(p_month date) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then raise exception 'Only an admin can settle a month.' using errcode = 'P0001'; end if;
  insert into periods (month) values (date_trunc('month', p_month)) on conflict do nothing;
  update periods set status = 'settled', settled_at = now(), settled_by = auth.uid()
   where month = date_trunc('month', p_month);
end $$;

create function reopen_month(p_month date, p_reason text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not is_admin() then raise exception 'Only an admin can reopen a month.' using errcode = 'P0001'; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'A reason is required.' using errcode = 'P0001'; end if;
  perform set_config('app.edit_reason', p_reason, true);
  update periods set status = 'open', settled_at = null, settled_by = null where month = date_trunc('month', p_month);
  insert into flags (rule, severity, entity_type, entity_id, period_month, message, details)
  values ('settled_month_edit', 'critical', 'period', extract(epoch from date_trunc('month', p_month))::bigint,
          date_trunc('month', p_month), format('%s reopened: %s', to_char(p_month, 'FMMonth YYYY'), p_reason),
          jsonb_build_object('reason', p_reason, 'by', auth.uid(), 'op', 'REOPEN'));
end $$;

-- Edit or delete a row with a recorded reason (required for settled months, optional otherwise).
-- Runs as the caller, so RLS and the lock trigger still apply.
create function edit_with_reason(p_table text, p_id bigint, p_patch jsonb, p_reason text) returns void
language plpgsql set search_path = public as $$
declare sets text; cols text;
begin
  if p_table not in ('purchase_lines', 'shipments', 'payments', 'credit_notes') then
    raise exception 'Table % cannot be edited this way.', p_table;
  end if;
  perform set_config('app.edit_reason', coalesce(p_reason, ''), true);

  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into cols
    from information_schema.columns
   where table_schema = 'public' and table_name = p_table
     and column_name in (select jsonb_object_keys(p_patch))
     and is_generated = 'NEVER' and is_identity = 'NO'
     and column_name not in ('id', 'created_at', 'created_by', 'updated_at', 'updated_by', 'import_ref');
  if cols is null then raise exception 'Nothing to update.'; end if;

  sets := format('(%s) = (select %s from jsonb_populate_record(null::%I, $1))', cols, cols, p_table);
  execute format('update %I set %s where id = $2', p_table, sets) using p_patch, p_id;
  if not found then raise exception 'Row not found or not permitted.'; end if;
end $$;

create function delete_with_reason(p_table text, p_id bigint, p_reason text) returns void
language plpgsql set search_path = public as $$
begin
  if p_table not in ('purchase_lines', 'shipments', 'payments', 'credit_notes') then
    raise exception 'Table % cannot be deleted this way.', p_table;
  end if;
  perform set_config('app.edit_reason', coalesce(p_reason, ''), true);
  execute format('delete from %I where id = $1', p_table) using p_id;
  if not found then raise exception 'Row not found or not permitted.'; end if;
end $$;

-- ---------------------------------------------------------------- row-level security

alter table companies      enable row level security;
alter table profiles       enable row level security;
alter table vendors        enable row level security;
alter table settings       enable row level security;
alter table products       enable row level security;
alter table listings       enable row level security;
alter table periods        enable row level security;
alter table fx_rates       enable row level security;
alter table shipments      enable row level security;
alter table purchase_lines enable row level security;
alter table payments       enable row level security;
alter table credit_notes   enable row level security;
alter table flags          enable row level security;
alter table audit_log      enable row level security;

-- reference data: everyone signed in can read; admins write
create policy read_all on companies for select to authenticated using (is_active_user());
create policy admin_write on companies for all to authenticated using (is_admin()) with check (is_admin());

create policy read_all on settings for select to authenticated using (is_active_user());
create policy admin_write on settings for all to authenticated using (is_admin()) with check (is_admin());

create policy read_all on periods for select to authenticated using (is_active_user());
create policy admin_write on periods for all to authenticated using (is_admin()) with check (is_admin());

create policy read_all on fx_rates for select to authenticated using (is_active_user());
create policy admin_write on fx_rates for all to authenticated using (is_admin()) with check (is_admin());

create policy read_all on vendors for select to authenticated using (is_active_user());
create policy staff_insert on vendors for insert to authenticated with check (is_staff());
create policy admin_update on vendors for update to authenticated using (is_admin()) with check (is_admin());
create policy admin_delete on vendors for delete to authenticated using (is_admin());

-- products & listings: staff can add and edit (rate card guarded by trigger); admins delete
create policy read_all on products for select to authenticated using (is_active_user());
create policy staff_insert on products for insert to authenticated with check (is_staff());
create policy staff_update on products for update to authenticated using (is_staff()) with check (is_staff());
create policy admin_delete on products for delete to authenticated using (is_admin());

create policy read_all on listings for select to authenticated using (is_active_user());
create policy staff_insert on listings for insert to authenticated with check (is_staff());
create policy staff_update on listings for update to authenticated using (is_staff()) with check (is_staff());
create policy admin_delete on listings for delete to authenticated using (is_admin());

-- purchases & shipments: staff write (settled months blocked by trigger)
create policy read_all on shipments for select to authenticated using (is_active_user());
create policy staff_write on shipments for all to authenticated using (is_staff()) with check (is_staff());

create policy read_all on purchase_lines for select to authenticated using (is_active_user());
create policy staff_write on purchase_lines for all to authenticated using (is_staff()) with check (is_staff());

-- money: admin and viewer read; admin writes
create policy money_read on payments for select to authenticated using (can_view_money());
create policy admin_write on payments for all to authenticated using (is_admin()) with check (is_admin());

create policy money_read on credit_notes for select to authenticated using (can_view_money());
create policy admin_write on credit_notes for all to authenticated using (is_admin()) with check (is_admin());

-- flags: data entry sees flags on purchases and shipments only
create policy read_flags on flags for select to authenticated
  using (can_view_money() or (is_staff() and entity_type in ('purchase_lines', 'shipments')));
create policy admin_update on flags for update to authenticated using (is_admin()) with check (is_admin());

create policy admin_read on audit_log for select to authenticated using (is_admin());

create policy read_own on profiles for select to authenticated using (id = auth.uid() or is_admin());
create policy admin_update on profiles for update to authenticated using (is_admin()) with check (is_admin());

-- Mark old flags as seen in bulk (e.g. everything from before the app went live).
create function acknowledge_flags_before(p_month date, p_rule text default null) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  if not is_admin() then raise exception 'Only an admin can do this.' using errcode = 'P0001'; end if;
  update flags set status = 'acknowledged', updated_at = now()
   where status = 'open' and period_month < p_month and (p_rule is null or rule = p_rule);
  get diagnostics n = row_count;
  return n;
end $$;

-- ===== supabase/migrations/20261121000003_flags_and_views.sql
-- Automatic flags, FX, landed cost and reconciliation.

create function setting_num(p_key text, p_default numeric) returns numeric
language sql stable security definer set search_path = public as $$
  select coalesce((select (value #>> '{}')::numeric from settings where key = p_key), p_default)
$$;

create function fmt_money(p_amount numeric, p_currency currency_code) returns text language sql immutable as $$
  select case p_currency when 'INR' then '₹' when 'GBP' then '£' when 'USD' then '$' else '¥' end
         || trim(to_char(p_amount, 'FM999,999,990.00'))
$$;

-- Raise (or refresh) a flag when p_active, otherwise auto-resolve it.
-- A flag a person resolved stays resolved; one that was auto-resolved re-opens if the problem returns.
create function set_flag(p_rule text, p_severity flag_severity, p_type text, p_id bigint, p_month date,
                         p_company text, p_active boolean, p_message text, p_details jsonb default '{}')
returns void language plpgsql security definer set search_path = public as $$
begin
  if p_active then
    insert into flags (rule, severity, entity_type, entity_id, period_month, company_code, message, details)
    values (p_rule, p_severity, p_type, p_id, p_month, p_company, p_message, p_details)
    on conflict (rule, entity_type, entity_id) where rule <> 'settled_month_edit'
    do update set message = excluded.message, details = excluded.details, severity = excluded.severity,
                  period_month = excluded.period_month, company_code = excluded.company_code, updated_at = now(),
                  status = case when flags.status = 'resolved' and flags.resolved_by is null then 'open'::flag_status
                                else flags.status end,
                  resolved_at = case when flags.status = 'resolved' and flags.resolved_by is null then null
                                     else flags.resolved_at end;
  else
    update flags set status = 'resolved', resolved_at = now(), resolution_note = 'Cleared automatically',
                     updated_at = now()
     where rule = p_rule and entity_type = p_type and entity_id = p_id and status <> 'resolved';
  end if;
end $$;

-- ---------------------------------------------------------------- purchase line rules

create function refresh_line_flags(p_line_id bigint) returns void
language plpgsql security definer set search_path = public as $$
declare
  l        record;
  prev     record;
  pct      numeric := setting_num('price_change_pct', 5);
  c_pct    numeric := setting_num('courier_change_pct', 0);
  tol      numeric := setting_num('rate_card_tolerance_pct', 0);
  low_inr  numeric := setting_num('suspect_inr_price_below', 20);
  t        text := 'purchase_lines';
begin
  select pl.*, p.name as product_name, p.agreed_courier_per_unit, p.agreed_courier_currency, p.agreed_courier_from
    into l
    from purchase_lines pl join products p on p.id = pl.product_id
   where pl.id = p_line_id;

  if not found then
    update flags set status = 'resolved', resolved_at = now(), resolution_note = 'Line deleted'
     where entity_type = t and entity_id = p_line_id and status <> 'resolved' and rule <> 'settled_month_edit';
    return;
  end if;

  -- the most recent purchase of the same product, in the same currency, in an earlier month
  select unit_price, courier_per_unit, period_month into prev
    from purchase_lines
   where product_id = l.product_id and currency = l.currency and period_month < l.period_month
     and unit_price is not null
   order by period_month desc, id desc
   limit 1;

  perform set_flag('price_change', 'warning', t, l.id, l.period_month, l.company_code,
    prev.unit_price is not null and l.unit_price is not null and prev.unit_price > 0
      and abs(l.unit_price - prev.unit_price) / prev.unit_price * 100 > pct,
    format('%s: price %s → %s (vs %s)', l.product_name, fmt_money(prev.unit_price, l.currency),
           fmt_money(l.unit_price, l.currency), to_char(prev.period_month, 'Mon YY')),
    jsonb_build_object('previous', prev.unit_price, 'current', l.unit_price, 'previous_month', prev.period_month));

  perform set_flag('courier_change', 'warning', t, l.id, l.period_month, l.company_code,
    prev.courier_per_unit is not null and prev.courier_per_unit <> l.courier_per_unit
      and (prev.courier_per_unit = 0
           or abs(l.courier_per_unit - prev.courier_per_unit) / prev.courier_per_unit * 100 > c_pct),
    format('%s: courier/unit %s → %s (vs %s)', l.product_name, fmt_money(prev.courier_per_unit, l.currency),
           fmt_money(l.courier_per_unit, l.currency), to_char(prev.period_month, 'Mon YY')),
    jsonb_build_object('previous', prev.courier_per_unit, 'current', l.courier_per_unit,
                       'previous_month', prev.period_month));

  perform set_flag('courier_above_price', 'warning', t, l.id, l.period_month, l.company_code,
    l.unit_price is not null and l.courier_per_unit > l.unit_price,
    format('%s: courier/unit %s is more than the product price %s', l.product_name,
           fmt_money(l.courier_per_unit, l.currency), fmt_money(l.unit_price, l.currency)));

  perform set_flag('courier_above_rate_card', 'critical', t, l.id, l.period_month, l.company_code,
    l.agreed_courier_per_unit is not null and l.agreed_courier_currency = l.currency
      and l.period_month >= coalesce(l.agreed_courier_from, '-infinity'::date)
      and l.courier_per_unit > l.agreed_courier_per_unit * (1 + tol / 100),
    format('%s: courier/unit %s is above the agreed %s', l.product_name,
           fmt_money(l.courier_per_unit, l.currency), fmt_money(l.agreed_courier_per_unit, l.currency)),
    jsonb_build_object('agreed', l.agreed_courier_per_unit, 'charged', l.courier_per_unit,
                       'excess_total', (l.courier_per_unit - l.agreed_courier_per_unit) * l.qty));

  perform set_flag('missing_invoice_no', 'warning', t, l.id, l.period_month, l.company_code,
    l.category = 'stock' and nullif(trim(coalesce(l.invoice_no, '')), '') is null,
    format('%s: no invoice number', l.product_name));

  perform set_flag('blank_price', 'critical', t, l.id, l.period_month, l.company_code,
    l.unit_price is null or l.unit_price = 0,
    format('%s: unit price is blank', l.product_name));

  perform set_flag('suspect_currency', 'warning', t, l.id, l.period_month, l.company_code,
    l.currency = 'INR' and l.unit_price > 0 and l.unit_price < low_inr,
    format('%s: ₹%s per unit looks like a £ price', l.product_name, l.unit_price));

  perform set_flag('receipt_discrepancy', 'info', t, l.id, l.period_month, l.company_code,
    (l.defective_qty + l.short_qty) > 0 and nullif(trim(coalesce(l.remarks, '') || coalesce(l.remarks_2, '')), '') is null,
    format('%s: %s defective, %s short, no remark', l.product_name, l.defective_qty, l.short_qty));
end $$;

-- ---------------------------------------------------------------- shipment rules

create function refresh_shipment_flags(p_id bigint) returns void
language plpgsql security definer set search_path = public as $$
declare
  s     record;
  days  numeric := setting_num('in_transit_days', 21);
  dup   bigint;
  t     text := 'shipments';
begin
  select * into s from shipments where id = p_id;
  if not found then
    update flags set status = 'resolved', resolved_at = now(), resolution_note = 'Shipment deleted'
     where entity_type = t and entity_id = p_id and status <> 'resolved' and rule <> 'settled_month_edit';
    return;
  end if;

  perform set_flag('long_in_transit', 'warning', t, s.id, s.period_month, s.company_code,
    s.status = 'in_transit' and coalesce(s.created_on, s.created_at::date) < current_date - days::int,
    format('Shipment %s has been in transit since %s',
           coalesce(s.amazon_shipment_id, s.tracking_no, s.box_no, '#' || s.id),
           to_char(coalesce(s.created_on, s.created_at::date), 'DD Mon YY')));

  select id into dup from shipments
   where id <> s.id and tracking_no is not null and upper(tracking_no) not in ('NA', 'N/A', 'TBA', '')
     and tracking_no = s.tracking_no
   limit 1;
  perform set_flag('duplicate_tracking', 'warning', t, s.id, s.period_month, s.company_code,
    dup is not null, format('Tracking no %s is also used by shipment #%s', s.tracking_no, dup));
end $$;

-- ---------------------------------------------------------------- payment rules

create function refresh_payment_flags(p_id bigint) returns void
language plpgsql security definer set search_path = public as $$
declare p record; t text := 'payments';
begin
  select * into p from payments where id = p_id;
  if not found then
    update flags set status = 'resolved', resolved_at = now(), resolution_note = 'Payment deleted'
     where entity_type = t and entity_id = p_id and status <> 'resolved' and rule <> 'settled_month_edit';
    return;
  end if;

  perform set_flag('unconfirmed_payment', 'warning', t, p.id, p.period_month, p.company_code,
    not p.confirmed,
    format('%s %s %s has no payment date, method or £ amount. Confirm it was actually paid.',
           p.company_code, p.kind, fmt_money(p.amount, p.currency)));

  perform set_flag('payment_missing_reference', 'info', t, p.id, p.period_month, p.company_code,
    p.confirmed and p.method ilike '%wise%' and nullif(trim(coalesce(p.reference, '')), '') is null,
    format('%s payment of %s has no Wise reference', p.company_code, fmt_money(p.amount, p.currency)));
end $$;

-- ---------------------------------------------------------------- triggers & batch refresh

create function flags_on_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare id bigint := case when tg_op = 'DELETE' then old.id else new.id end;
begin
  if is_importing() then return null; end if;
  case tg_table_name
    when 'purchase_lines' then perform refresh_line_flags(id);
    when 'shipments'      then perform refresh_shipment_flags(id);
    when 'payments'       then perform refresh_payment_flags(id);
  end case;
  return null;
end $$;

create trigger y_flags after insert or update or delete on purchase_lines for each row execute function flags_on_change();
create trigger y_flags after insert or update or delete on shipments      for each row execute function flags_on_change();
create trigger y_flags after insert or update or delete on payments       for each row execute function flags_on_change();

-- Run nightly (pg_cron) and after an import. Also catches knock-on effects, e.g. a rate-card change.
create function refresh_all_flags() returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in select id from purchase_lines loop perform refresh_line_flags(r.id); n := n + 1; end loop;
  for r in select id from shipments      loop perform refresh_shipment_flags(r.id); end loop;
  for r in select id from payments       loop perform refresh_payment_flags(r.id); end loop;
  return n;
end $$;

-- Weighted ₹/£ from each month's confirmed INR payments. Manual rates are never overwritten.
create function recompute_fx_from_payments() returns void
language sql security definer set search_path = public as $$
  insert into fx_rates (month, inr_per_gbp, source)
  select period_month, round(sum(amount) / sum(amount_gbp), 4), 'payments'
    from payments
   where currency = 'INR' and confirmed and amount_gbp > 0 and amount > 0
   group by period_month
  on conflict (month) do update set inr_per_gbp = excluded.inr_per_gbp, updated_at = now()
   where fx_rates.source <> 'manual';
$$;

-- ---------------------------------------------------------------- views (RLS of the caller applies)

-- Rate for each month: that month's, else the most recent earlier one, else the default setting.
create view v_fx with (security_invoker = true) as
select p.month,
       coalesce(
         (select f.inr_per_gbp from fx_rates f where f.month <= p.month order by f.month desc limit 1),
         setting_num('default_inr_per_gbp', 125)) as inr_per_gbp,
       (select f.source from fx_rates f where f.month = p.month) as source
  from periods p;

create view v_purchase_lines with (security_invoker = true) as
select pl.*,
       p.name   as product_name,
       p.agreed_courier_per_unit,
       c.name   as company_name,
       v.name   as vendor_name,
       v.kind   as vendor_kind,
       li.asin, li.fnsku, li.channel,
       s.box_no, s.amazon_shipment_id, s.tracking_no, s.status as shipment_status, s.received_on,
       fx.inr_per_gbp,
       (coalesce(pl.unit_price, 0) + pl.courier_per_unit) as landed_per_unit,
       case pl.currency when 'INR' then coalesce(pl.unit_price, 0) + pl.courier_per_unit
                        when 'GBP' then (coalesce(pl.unit_price, 0) + pl.courier_per_unit) * fx.inr_per_gbp end
         as landed_per_unit_inr,
       case pl.currency when 'GBP' then coalesce(pl.unit_price, 0) + pl.courier_per_unit
                        when 'INR' then (coalesce(pl.unit_price, 0) + pl.courier_per_unit) / fx.inr_per_gbp end
         as landed_per_unit_gbp,
       case when pl.received_qty > 0 then pl.line_total / pl.received_qty end as landed_per_received_unit,
       case pl.currency when 'INR' then pl.line_total when 'GBP' then pl.line_total * fx.inr_per_gbp end as line_total_inr,
       case pl.currency when 'GBP' then pl.line_total when 'INR' then pl.line_total / fx.inr_per_gbp end as line_total_gbp
  from purchase_lines pl
  join products p   on p.id = pl.product_id
  join companies c  on c.code = pl.company_code
  join vendors v    on v.id = pl.vendor_id
  left join listings li  on li.id = pl.listing_id
  left join shipments s  on s.id = pl.shipment_id
  left join v_fx fx      on fx.month = pl.period_month;

create view v_landed_cost with (security_invoker = true) as
select period_month, company_code, product_id, product_name, currency,
       sum(qty)                                   as qty,
       sum(received_qty)                          as received_qty,
       sum(line_total)                            as total_cost,
       round(sum(line_total) / nullif(sum(qty), 0), 2)            as landed_per_unit,
       round(sum(line_total_inr) / nullif(sum(qty), 0), 2)        as landed_per_unit_inr,
       round(sum(line_total_gbp) / nullif(sum(qty), 0), 4)        as landed_per_unit_gbp,
       round(sum(line_total) / nullif(sum(received_qty), 0), 2)   as landed_per_received_unit
  from v_purchase_lines
 group by period_month, company_code, product_id, product_name, currency;

-- Balance owed to each vendor by each company, month by month, in the vendor's currency.
create view v_reconciliation with (security_invoker = true) as
with movements as (
  select vendor_id, company_code, period_month, currency,
         sum(line_total) as purchases, 0::numeric as credit_notes, 0::numeric as payments, 0::numeric as unconfirmed
    from purchase_lines group by 1, 2, 3, 4
  union all
  select vendor_id, company_code, period_month, currency, 0, sum(amount), 0, 0
    from credit_notes group by 1, 2, 3, 4
  union all
  select vendor_id, company_code, period_month, currency, 0, 0,
         sum(amount) filter (where confirmed), coalesce(sum(amount) filter (where not confirmed), 0)
    from payments group by 1, 2, 3, 4
), monthly as (
  select vendor_id, company_code, period_month, currency,
         sum(purchases) as purchases, sum(credit_notes) as credit_notes,
         coalesce(sum(payments), 0) as payments, sum(unconfirmed) as unconfirmed_payments
    from movements group by 1, 2, 3, 4
)
select m.*,
       v.name as vendor_name,
       coalesce(sum(m.purchases - m.credit_notes - m.payments) over w_prev, 0) as opening_balance,
       m.purchases - m.credit_notes - m.payments                            as movement,
       sum(m.purchases - m.credit_notes - m.payments) over w_to_date        as closing_balance,
       per.status as period_status
  from monthly m
  join vendors v on v.id = m.vendor_id
  join periods per on per.month = m.period_month
 where can_view_money()
window w_prev    as (partition by m.vendor_id, m.company_code, m.currency order by m.period_month
                     rows between unbounded preceding and 1 preceding),
       w_to_date as (partition by m.vendor_id, m.company_code, m.currency order by m.period_month);


-- What is owed to each vendor overall, month by month. This is the main reconciliation:
-- payments go out from whichever company account suits, so the vendor balance is what matters;
-- v_reconciliation gives the per-company breakdown (rows with no company = vendor-level credit notes).
create view v_vendor_balance with (security_invoker = true) as
with monthly as (
  select vendor_id, period_month, currency,
         sum(purchases) as purchases, sum(credit_notes) as credit_notes,
         sum(payments) as payments, sum(unconfirmed_payments) as unconfirmed_payments
    from v_reconciliation
   group by 1, 2, 3
)
select m.*,
       v.name as vendor_name,
       coalesce(sum(m.purchases - m.credit_notes - m.payments) over w_prev, 0) as opening_balance,
       m.purchases - m.credit_notes - m.payments                            as movement,
       sum(m.purchases - m.credit_notes - m.payments) over w_to_date        as closing_balance,
       per.status as period_status
  from monthly m
  join vendors v on v.id = m.vendor_id
  join periods per on per.month = m.period_month
window w_prev    as (partition by m.vendor_id, m.currency order by m.period_month
                     rows between unbounded preceding and 1 preceding),
       w_to_date as (partition by m.vendor_id, m.currency order by m.period_month);

-- Which bank account paid for which company's stock. A row where the paying account is not the company's
-- own (another company, or a personal account) is money one party owes another.
create view v_payments_by_account with (security_invoker = true) as
select p.period_month,
       p.company_code                                    as paid_for,
       coalesce(p.paid_from_company, p.paid_from, '?')   as paid_from_account,
       p.paid_from_company is distinct from p.company_code as on_behalf,
       p.currency,
       count(*)                                          as payments,
       sum(p.amount)                                     as amount,
       sum(p.amount_gbp)                                 as amount_gbp
  from payments p
 where p.confirmed and can_view_money()
 group by 1, 2, 3, 4, 5;

-- ===== supabase/migrations/20261121000004_grants.sql
-- Table access for signed-in users. Older Supabase projects grant this by default; newer ones may not.
-- Row-level security (migration 002) still decides which rows each role can see or change.
grant usage on schema public to anon, authenticated;
grant select, insert, update, delete on all tables in schema public to authenticated;
grant usage, select on all sequences in schema public to authenticated;
grant execute on all functions in schema public to authenticated;
alter default privileges in schema public grant select, insert, update, delete on tables to authenticated;
alter default privileges in schema public grant usage, select on sequences to authenticated;
alter default privileges in schema public grant execute on functions to authenticated;

-- ===== supabase/migrations/20261122000005_dashboard.sql
-- DSH-01 / DSH-02: monthly purchasing overview, calculated in one place.
-- A purchase belongs to the month of its invoice (order) date; lines imported without one fall back to their sheet month.
-- "Current month" is the Europe/London month.
-- Units count stock only (packaging/stationery is left out); spend includes every purchase.
-- INR and GBP are summed separately and never converted.
create function dashboard_monthly(p_months integer default 12, p_end date default null)
returns table (month date, units bigint, spend_inr numeric, spend_gbp numeric, missing_currency bigint)
language sql stable security invoker set search_path = public as $$
  with bounds as (
    select date_trunc('month', coalesce(p_end, (now() at time zone 'Europe/London')::date))::date as last_month
  ), months as (
    select generate_series(b.last_month - make_interval(months => greatest(p_months, 1) - 1), b.last_month, interval '1 month')::date as month
      from bounds b
  )
  select m.month,
         coalesce(sum(pl.qty) filter (where pl.category = 'stock'), 0)::bigint,
         coalesce(sum(pl.line_total) filter (where pl.currency = 'INR'), 0),
         coalesce(sum(pl.line_total) filter (where pl.currency = 'GBP'), 0),
         count(pl.id) filter (where pl.currency is null)
    from months m
    left join purchase_lines pl on date_trunc('month', coalesce(pl.invoice_date, pl.period_month))::date = m.month
   group by m.month
   order by m.month
$$;

grant execute on function dashboard_monthly(integer, date) to authenticated;

-- ===== supabase/migrations/20261122000006_invoices.sql
-- INV-01..03: invoice dates are required on new purchases, invoice files can be uploaded and listed.

-- ---------------------------------------------------------------- invoice date rules

-- New stock purchases must carry an invoice date, and are filed in that invoice's month.
create function purchase_invoice_rules() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if is_importing() then return new; end if;
  if tg_op = 'UPDATE' then
    -- an invoice date can be corrected but not removed; the line stays in the month it was filed under
    if old.invoice_date is not null and new.invoice_date is null then
      raise exception 'The invoice date cannot be removed.' using errcode = 'P0001';
    end if;
    return new;
  end if;
  if new.category = 'stock' and new.invoice_date is null then
    raise exception 'Enter the invoice date.' using errcode = 'P0001';
  end if;
  if new.invoice_date is not null then
    new.period_month := date_trunc('month', new.invoice_date)::date;
  end if;
  return new;
end $$;

-- runs before a_ensure_period / b_period_lock (triggers fire in name order)
create trigger a0_invoice_rules before insert or update of invoice_date on purchase_lines
  for each row execute function purchase_invoice_rules();

-- flag older lines without an invoice date
create or replace function refresh_line_flags(p_line_id bigint) returns void
language plpgsql security definer set search_path = public as $$
declare
  l        record;
  prev     record;
  pct      numeric := setting_num('price_change_pct', 5);
  c_pct    numeric := setting_num('courier_change_pct', 0);
  tol      numeric := setting_num('rate_card_tolerance_pct', 0);
  low_inr  numeric := setting_num('suspect_inr_price_below', 20);
  t        text := 'purchase_lines';
begin
  select pl.*, p.name as product_name, p.agreed_courier_per_unit, p.agreed_courier_currency, p.agreed_courier_from
    into l
    from purchase_lines pl join products p on p.id = pl.product_id
   where pl.id = p_line_id;

  if not found then
    update flags set status = 'resolved', resolved_at = now(), resolution_note = 'Line deleted'
     where entity_type = t and entity_id = p_line_id and status <> 'resolved' and rule <> 'settled_month_edit';
    return;
  end if;

  -- the most recent purchase of the same product, in the same currency, in an earlier month
  select unit_price, courier_per_unit, period_month into prev
    from purchase_lines
   where product_id = l.product_id and currency = l.currency and period_month < l.period_month
     and unit_price is not null
   order by period_month desc, id desc
   limit 1;

  perform set_flag('price_change', 'warning', t, l.id, l.period_month, l.company_code,
    prev.unit_price is not null and l.unit_price is not null and prev.unit_price > 0
      and abs(l.unit_price - prev.unit_price) / prev.unit_price * 100 > pct,
    format('%s: price %s → %s (vs %s)', l.product_name, fmt_money(prev.unit_price, l.currency),
           fmt_money(l.unit_price, l.currency), to_char(prev.period_month, 'Mon YY')),
    jsonb_build_object('previous', prev.unit_price, 'current', l.unit_price, 'previous_month', prev.period_month));

  perform set_flag('courier_change', 'warning', t, l.id, l.period_month, l.company_code,
    prev.courier_per_unit is not null and prev.courier_per_unit <> l.courier_per_unit
      and (prev.courier_per_unit = 0
           or abs(l.courier_per_unit - prev.courier_per_unit) / prev.courier_per_unit * 100 > c_pct),
    format('%s: courier/unit %s → %s (vs %s)', l.product_name, fmt_money(prev.courier_per_unit, l.currency),
           fmt_money(l.courier_per_unit, l.currency), to_char(prev.period_month, 'Mon YY')),
    jsonb_build_object('previous', prev.courier_per_unit, 'current', l.courier_per_unit,
                       'previous_month', prev.period_month));

  perform set_flag('courier_above_price', 'warning', t, l.id, l.period_month, l.company_code,
    l.unit_price is not null and l.courier_per_unit > l.unit_price,
    format('%s: courier/unit %s is more than the product price %s', l.product_name,
           fmt_money(l.courier_per_unit, l.currency), fmt_money(l.unit_price, l.currency)));

  perform set_flag('courier_above_rate_card', 'critical', t, l.id, l.period_month, l.company_code,
    l.agreed_courier_per_unit is not null and l.agreed_courier_currency = l.currency
      and l.period_month >= coalesce(l.agreed_courier_from, '-infinity'::date)
      and l.courier_per_unit > l.agreed_courier_per_unit * (1 + tol / 100),
    format('%s: courier/unit %s is above the agreed %s', l.product_name,
           fmt_money(l.courier_per_unit, l.currency), fmt_money(l.agreed_courier_per_unit, l.currency)),
    jsonb_build_object('agreed', l.agreed_courier_per_unit, 'charged', l.courier_per_unit,
                       'excess_total', (l.courier_per_unit - l.agreed_courier_per_unit) * l.qty));

  perform set_flag('missing_invoice_no', 'warning', t, l.id, l.period_month, l.company_code,
    l.category = 'stock' and nullif(trim(coalesce(l.invoice_no, '')), '') is null,
    format('%s: no invoice number', l.product_name));

  perform set_flag('blank_price', 'critical', t, l.id, l.period_month, l.company_code,
    l.unit_price is null or l.unit_price = 0,
    format('%s: unit price is blank', l.product_name));

  perform set_flag('suspect_currency', 'warning', t, l.id, l.period_month, l.company_code,
    l.currency = 'INR' and l.unit_price > 0 and l.unit_price < low_inr,
    format('%s: ₹%s per unit looks like a £ price', l.product_name, l.unit_price));

  perform set_flag('receipt_discrepancy', 'info', t, l.id, l.period_month, l.company_code,
    (l.defective_qty + l.short_qty) > 0 and nullif(trim(coalesce(l.remarks, '') || coalesce(l.remarks_2, '')), '') is null,
    format('%s: %s defective, %s short, no remark', l.product_name, l.defective_qty, l.short_qty));

  perform set_flag('missing_invoice_date', 'warning', t, l.id, l.period_month, l.company_code,
    l.category = 'stock' and l.invoice_date is null,
    format('%s: no invoice date', l.product_name));
end $$;

-- ---------------------------------------------------------------- invoice files

create table invoice_files (
  id            bigint generated always as identity primary key,
  company_code  text references companies (code),
  vendor_id     bigint references vendors (id),
  invoice_no    text,
  invoice_date  date,
  storage_path  text not null unique,          -- path inside the private "invoices" storage bucket
  file_name     text not null,
  content_type  text,
  size_bytes    integer,
  uploaded_by   uuid references auth.users (id) default auth.uid(),
  uploaded_at   timestamptz not null default now()
);
create index invoice_files_lookup_idx on invoice_files (vendor_id, invoice_no);

alter table invoice_files enable row level security;
create policy read_all on invoice_files for select to authenticated using (is_active_user());
create policy staff_insert on invoice_files for insert to authenticated with check (is_staff());
create policy admin_update on invoice_files for update to authenticated using (is_admin()) with check (is_admin());
create policy admin_delete on invoice_files for delete to authenticated using (is_admin());
create trigger z_audit after insert or update or delete on invoice_files for each row execute function write_audit();
grant select, insert, update, delete on invoice_files to authenticated;

-- One row per invoice (vendor + company + invoice no.), with its purchase totals and how many files are attached.
create view v_invoices with (security_invoker = true) as
select pl.vendor_id,
       v.name                         as vendor_name,
       pl.company_code,
       pl.invoice_no,
       min(pl.invoice_date)           as invoice_date,
       min(pl.period_month)           as period_month,
       count(*)                       as lines,
       sum(pl.qty)                    as units,
       sum(pl.line_total) filter (where pl.currency = 'INR') as total_inr,
       sum(pl.line_total) filter (where pl.currency = 'GBP') as total_gbp,
       (select count(*) from invoice_files f
         where f.vendor_id = pl.vendor_id and f.invoice_no = pl.invoice_no
           and (f.company_code is null or f.company_code = pl.company_code)) as files
  from purchase_lines pl
  join vendors v on v.id = pl.vendor_id
 where pl.invoice_no is not null
 group by pl.vendor_id, v.name, pl.company_code, pl.invoice_no;
grant select on v_invoices to authenticated;

-- ---------------------------------------------------------------- storage bucket (Supabase only)

do $$
begin
  if exists (select 1 from pg_namespace where nspname = 'storage') then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('invoices', 'invoices', false, 10485760,
            array['application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'image/heic'])
    on conflict (id) do nothing;
    execute $p$create policy "invoices: read" on storage.objects for select to authenticated
             using (bucket_id = 'invoices' and public.is_active_user())$p$;
    execute $p$create policy "invoices: upload" on storage.objects for insert to authenticated
             with check (bucket_id = 'invoices' and public.is_staff())$p$;
    execute $p$create policy "invoices: delete" on storage.objects for delete to authenticated
             using (bucket_id = 'invoices' and public.is_admin())$p$;
  end if;
end $$;

select refresh_all_flags();

-- ===== supabase/migrations/20261125000008_boxes.sql
-- PUR-06: a box (shipment) holds products from any invoice; a purchase line can be split across boxes.
-- Decisions 25 Nov 2026: receipts per box for split lines; FBM/UK boxes may mix companies; "30 of 50 shipped";
-- contents can change while the box is In transit, not after it is received.
-- purchase_lines.shipment_id is kept in step: it is the box when the line is in exactly one box, so every
-- existing screen and flag keeps working for single-box lines.

create table shipment_items (
  id                bigint generated always as identity primary key,
  shipment_id       bigint not null references shipments (id) on delete cascade,
  purchase_line_id  bigint not null references purchase_lines (id) on delete cascade,
  qty               integer not null check (qty > 0),
  defective_qty     integer not null default 0 check (defective_qty >= 0),
  short_qty         integer not null default 0 check (short_qty >= 0),
  remarks           text,
  created_by        uuid references auth.users (id) default auth.uid(),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (shipment_id, purchase_line_id)
);
create index shipment_items_line_idx on shipment_items (purchase_line_id);

-- every line already linked to a box becomes that box's contents, with its receipt
insert into shipment_items (shipment_id, purchase_line_id, qty, defective_qty, short_qty)
select shipment_id, id, qty, defective_qty, short_qty from purchase_lines where shipment_id is not null and qty > 0;

-- linking a line to a box, and the receipt fields, are not money: allowed after a month is settled
create or replace function receipt_columns(p_table text) returns text[] language sql immutable as $$
  select case p_table
    when 'shipments' then array['status', 'received_on', 'received_by', 'tracking_no', 'courier', 'notes', 'updated_at']
    -- generated totals are listed too: they are not yet computed in a BEFORE trigger, and follow from the other columns
    when 'purchase_lines' then array['defective_qty', 'short_qty', 'received_qty', 'checked_by', 'remarks', 'remarks_2',
                                     'amazon_case_id', 'reimbursement_id', 'reimbursed_gbp', 'updated_at', 'updated_by',
                                     'courier_total', 'goods_total', 'line_total', 'shipment_id']
    else array[]::text[] end
$$;

create function flag_on(p_name text) returns boolean language sql stable as $$
  select coalesce(current_setting('app.' || p_name, true), '') = 'on'
$$;

-- ---------------------------------------------------------------- box contents rules

create function shipment_item_rules() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  box record; line record; others integer; other_company text;
  r shipment_items := case when tg_op = 'DELETE' then old else new end;
  contents_change boolean;
begin
  select * into box from shipments where id = r.shipment_id;
  contents_change := tg_op <> 'UPDATE'
    or (new.qty, new.shipment_id, new.purchase_line_id) is distinct from (old.qty, old.shipment_id, old.purchase_line_id);

  -- contents are fixed once the box is received (receipts can still be recorded)
  if contents_change and box.status <> 'in_transit' and not flag_on('items_from_line') and not is_importing() then
    raise exception 'Box % has already been received: its contents cannot change.',
      coalesce(box.amazon_shipment_id, box.box_no, '#' || box.id) using errcode = 'P0001';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  -- the rules below are about what goes into a box: recording a receipt never trips them,
  -- and history loaded from the spreadsheet is taken as it was
  if not contents_change or is_importing() then
    new.updated_at := now();
    return new;
  end if;

  select * into line from purchase_lines where id = new.purchase_line_id;

  -- never more units in boxes than were bought
  select coalesce(sum(qty), 0) into others from shipment_items
   where purchase_line_id = new.purchase_line_id and id <> coalesce(new.id, -1);
  if others + new.qty > line.qty then
    raise exception 'Only % of % units are left to put in a box.', greatest(line.qty - others, 0), line.qty using errcode = 'P0001';
  end if;

  -- an Amazon (FBA) box holds one company's stock; FBM/UK boxes may mix
  if box.channel = 'FBA' or box.amazon_shipment_id is not null then
    select pl.company_code into other_company from shipment_items i join purchase_lines pl on pl.id = i.purchase_line_id
     where i.shipment_id = new.shipment_id and i.id <> coalesce(new.id, -1) and pl.company_code <> line.company_code limit 1;
    if other_company is not null or (box.company_code is not null and box.company_code <> line.company_code) then
      raise exception 'An Amazon shipment can only hold one company''s stock.' using errcode = 'P0001';
    end if;
  end if;

  new.updated_at := now();
  return new;
end $$;

create trigger a_item_rules before insert or update or delete on shipment_items
  for each row execute function shipment_item_rules();

-- receipts per box add up on the line; the line's box is set when it is in exactly one box
create function sync_line_from_items(p_line bigint) returns void
language plpgsql security definer set search_path = public as $$
declare n integer; d integer; s integer; only_box bigint;
begin
  select count(*), coalesce(sum(defective_qty), 0), coalesce(sum(short_qty), 0), min(shipment_id)
    into n, d, s, only_box from shipment_items where purchase_line_id = p_line;
  perform set_config('app.items_sync', 'on', true);
  if n = 0 then
    update purchase_lines set shipment_id = null where id = p_line and shipment_id is not null;
  else
    update purchase_lines set defective_qty = d, short_qty = s, shipment_id = case when n = 1 then only_box end
     where id = p_line and (defective_qty, short_qty, shipment_id) is distinct from (d, s, case when n = 1 then only_box end);
  end if;
  perform set_config('app.items_sync', 'off', true);
end $$;

create function items_changed() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op <> 'INSERT' then perform sync_line_from_items(old.purchase_line_id); end if;
  if tg_op <> 'DELETE' and (tg_op = 'INSERT' or new.purchase_line_id <> old.purchase_line_id
                            or (new.defective_qty, new.short_qty, new.shipment_id) is distinct from (old.defective_qty, old.short_qty, old.shipment_id)) then
    perform sync_line_from_items(new.purchase_line_id);
  end if;
  return null;
end $$;

create trigger y_items_changed after insert or update or delete on shipment_items
  for each row execute function items_changed();

-- ---------------------------------------------------------------- the line side

-- Changes made on the line itself (as before PUR-06) are refused or passed to its single box.
create function line_box_rules() returns trigger
language plpgsql security definer set search_path = public as $$
declare n integer; boxed integer;
begin
  if flag_on('items_sync') or is_importing() then return new; end if;
  select count(*), coalesce(sum(qty), 0) into n, boxed from shipment_items where purchase_line_id = new.id;
  if n = 0 then return new; end if;
  if new.qty < boxed and not (n = 1 and boxed = old.qty) then
    raise exception '% units of this line are already in boxes.', boxed using errcode = 'P0001';
  end if;
  if n > 1 and (new.defective_qty, new.short_qty) is distinct from (old.defective_qty, old.short_qty) then
    raise exception 'This line is in % boxes. Record shortages on each box.', n using errcode = 'P0001';
  end if;
  if n > 1 and new.shipment_id is distinct from old.shipment_id then
    raise exception 'This line is in % boxes. Change it on each box.', n using errcode = 'P0001';
  end if;
  return new;
end $$;

create trigger a1_line_box_rules before update on purchase_lines
  for each row execute function line_box_rules();

-- ...and mirrored onto the box contents after the line is saved
create function line_to_items() returns trigger
language plpgsql security definer set search_path = public as $$
declare item shipment_items;
begin
  if flag_on('items_sync') then return null; end if;
  perform set_config('app.items_from_line', 'on', true);
  if tg_op = 'INSERT' then
    if new.shipment_id is not null and new.qty > 0 then
      insert into shipment_items (shipment_id, purchase_line_id, qty, defective_qty, short_qty)
      values (new.shipment_id, new.id, new.qty, new.defective_qty, new.short_qty);
    end if;
  else
    select * into item from shipment_items where purchase_line_id = new.id;
    if (select count(*) from shipment_items where purchase_line_id = new.id) = 1 then
      update shipment_items set
        qty = case when item.qty = old.qty then new.qty else qty end,
        defective_qty = new.defective_qty, short_qty = new.short_qty,
        shipment_id = coalesce(new.shipment_id, shipment_id)
       where id = item.id
         and (qty, defective_qty, short_qty, shipment_id) is distinct from
             (case when item.qty = old.qty then new.qty else item.qty end, new.defective_qty, new.short_qty, coalesce(new.shipment_id, item.shipment_id));
      if new.shipment_id is null and old.shipment_id is not null then delete from shipment_items where id = item.id; end if;
    elsif item.id is null and new.shipment_id is not null and new.qty > 0 then
      insert into shipment_items (shipment_id, purchase_line_id, qty, defective_qty, short_qty)
      values (new.shipment_id, new.id, new.qty, new.defective_qty, new.short_qty);
    end if;
  end if;
  perform set_config('app.items_from_line', 'off', true);
  return null;
end $$;

create trigger y_line_to_items after insert or update of qty, defective_qty, short_qty, shipment_id on purchase_lines
  for each row execute function line_to_items();

-- ---------------------------------------------------------------- "Put in one box"

-- p_lines: [{"line_id": 1, "qty": 50}, ...]; p_shipment: an existing box, or null to create one from p_new
-- (company_code, box_no, amazon_shipment_id, tracking_no, courier, created_on, channel). Returns the box id.
create function put_in_box(p_lines jsonb, p_shipment bigint, p_new jsonb) returns bigint
language plpgsql set search_path = public as $$
declare sid bigint := p_shipment; l jsonb; existing shipment_items; d date; left_qty integer; line_qty integer;
begin
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Tick at least one line.' using errcode = 'P0001';
  end if;
  if sid is null then
    d := coalesce(nullif(p_new ->> 'created_on', '')::date, (now() at time zone 'Europe/London')::date);
    insert into shipments (period_month, company_code, channel, box_no, amazon_shipment_id, tracking_no, courier, created_on, status)
    values (d, nullif(p_new ->> 'company_code', ''),
            coalesce(nullif(p_new ->> 'channel', ''), case when nullif(p_new ->> 'amazon_shipment_id', '') is not null then 'FBA' else 'FBM' end)::sales_channel,
            nullif(p_new ->> 'box_no', ''), upper(nullif(p_new ->> 'amazon_shipment_id', '')), nullif(p_new ->> 'tracking_no', ''),
            nullif(p_new ->> 'courier', ''), d, 'in_transit')
    returning id into sid;
  end if;
  for l in select * from jsonb_array_elements(p_lines) loop
    if coalesce((l ->> 'qty')::int, 0) <= 0 then continue; end if;
    -- units of the line not yet in any box
    select pl.qty - coalesce((select sum(qty) from shipment_items where purchase_line_id = pl.id), 0), pl.qty
      into left_qty, line_qty from purchase_lines pl where pl.id = (l ->> 'line_id')::bigint;
    if (l ->> 'qty')::int > left_qty then
      raise exception 'Only % of % units are left to put in a box.', greatest(left_qty, 0), line_qty using errcode = 'P0001';
    end if;
    select * into existing from shipment_items where shipment_id = sid and purchase_line_id = (l ->> 'line_id')::bigint;
    if existing.id is not null then
      update shipment_items set qty = qty + (l ->> 'qty')::int where id = existing.id;
    else
      insert into shipment_items (shipment_id, purchase_line_id, qty) values (sid, (l ->> 'line_id')::bigint, (l ->> 'qty')::int);
    end if;
  end loop;
  return sid;
end $$;

-- ---------------------------------------------------------------- what is in each box, and where each line went

create view v_shipment_contents with (security_invoker = true) as
select i.id, i.shipment_id, i.purchase_line_id, p.name as product_name, pl.invoice_no, pl.company_code, pl.period_month,
       i.qty, i.defective_qty, i.short_qty, i.qty - i.defective_qty - i.short_qty as received_qty, i.remarks,
       pl.qty as line_qty
  from shipment_items i
  join purchase_lines pl on pl.id = i.purchase_line_id
  join products p on p.id = pl.product_id;

create view v_shipment_totals with (security_invoker = true) as
select shipment_id, count(*) as products, sum(qty) as units from shipment_items group by shipment_id;

create view v_line_boxes with (security_invoker = true) as
select pl.id as purchase_line_id, pl.qty as line_qty, sum(i.qty)::int as boxed_qty, count(*)::int as box_count,
       case when sum(i.qty) >= pl.qty then format('%s shipped in %s box%s', pl.qty, count(*), case when count(*) = 1 then '' else 'es' end)
            else format('%s of %s shipped', sum(i.qty), pl.qty) end as summary
  from shipment_items i join purchase_lines pl on pl.id = i.purchase_line_id
 group by pl.id, pl.qty;

-- ---------------------------------------------------------------- access

alter table shipment_items enable row level security;
create policy read_all on shipment_items for select to authenticated using (is_active_user());
create policy staff_write on shipment_items for all to authenticated using (is_staff()) with check (is_staff());
grant select, insert, update, delete on shipment_items to authenticated;
grant select on v_shipment_contents, v_shipment_totals, v_line_boxes to authenticated;
create trigger z_audit after insert or update or delete on shipment_items for each row execute function write_audit();

-- ===== supabase/migrations/20261125000009_daily_fx.sql
-- UI-04 (decision B, 25 Nov 2026): the European Central Bank's daily £→₹ rate.
-- Shown on the dashboard, and used to convert purchases with an invoice date from 25 Nov 2026 onwards:
-- the rate of the invoice date, or the last one published before it (weekends, holidays).
-- The rate used is stored on each line, so its cost never shifts later. Earlier purchases keep the monthly
-- Wise rate (LC-03). Supplier balances and payments are not converted, so they never change with the rate.

create table daily_fx_rates (
  rate_date    date primary key,
  inr_per_gbp  numeric(12, 4) not null check (inr_per_gbp > 0),
  eur_inr      numeric(12, 4),
  eur_gbp      numeric(12, 5),
  source       text not null default 'European Central Bank',
  fetched_at   timestamptz not null default now()
);
alter table daily_fx_rates enable row level security;
create policy read_all on daily_fx_rates for select to authenticated using (is_active_user());
grant select on daily_fx_rates to authenticated;   -- no one writes except the server's daily fetch (below)

insert into settings (key, value, description)
values ('daily_fx_from', '"2026-11-25"', 'Purchases invoiced from this date use the ECB daily rate (UI-04)')
on conflict (key) do nothing;

create function daily_fx_from() returns date language sql stable security definer set search_path = public as $$
  select coalesce((select (value #>> '{}')::date from settings where key = 'daily_fx_from'), '2026-11-25'::date)
$$;

alter table purchase_lines
  add column fx_inr_per_gbp numeric(12, 4),   -- daily rate used for this line (null = monthly Wise rate)
  add column fx_rate_date   date;

create function daily_rate_for(p_day date) returns daily_fx_rates
language sql stable security definer set search_path = public as $$
  select * from daily_fx_rates where rate_date <= p_day order by rate_date desc limit 1
$$;

-- a new purchase (or a corrected invoice date) takes the daily rate of its invoice date
create function line_daily_fx() returns trigger
language plpgsql security definer set search_path = public as $$
declare r daily_fx_rates;
begin
  if is_importing() then return new; end if;
  if tg_op = 'UPDATE' and new.invoice_date is not distinct from old.invoice_date then return new; end if;
  if new.invoice_date is null or new.invoice_date < daily_fx_from() then
    new.fx_inr_per_gbp := null; new.fx_rate_date := null;
    return new;
  end if;
  r := daily_rate_for(new.invoice_date);
  new.fx_inr_per_gbp := r.inr_per_gbp;   -- null until the first rate is fetched; filled in then (below)
  new.fx_rate_date := r.rate_date;
  return new;
end $$;
create trigger a2_line_daily_fx before insert or update of invoice_date on purchase_lines
  for each row execute function line_daily_fx();

-- The server's daily fetch: rows [{"date", "eur_inr", "eur_gbp"}] from the ECB. Only the service key may call it.
create function store_daily_rates(p_rates jsonb) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  insert into daily_fx_rates (rate_date, inr_per_gbp, eur_inr, eur_gbp, fetched_at)
  select (x ->> 'date')::date, round((x ->> 'eur_inr')::numeric / (x ->> 'eur_gbp')::numeric, 4),
         (x ->> 'eur_inr')::numeric, (x ->> 'eur_gbp')::numeric, now()
    from jsonb_array_elements(p_rates) x
   where (x ->> 'eur_inr')::numeric > 0 and (x ->> 'eur_gbp')::numeric > 0
  on conflict (rate_date) do update
     set inr_per_gbp = excluded.inr_per_gbp, eur_inr = excluded.eur_inr, eur_gbp = excluded.eur_gbp, fetched_at = now();
  get diagnostics n = row_count;

  -- purchases saved before any rate was available get theirs now; lines that already have a rate keep it
  perform set_config('app.bypass_lock', 'on', true);
  update purchase_lines pl
     set (fx_inr_per_gbp, fx_rate_date) = (select r.inr_per_gbp, r.rate_date from daily_rate_for(pl.invoice_date) r)
   where pl.fx_inr_per_gbp is null and pl.invoice_date >= daily_fx_from()
     and exists (select 1 from daily_fx_rates d where d.rate_date <= pl.invoice_date);
  perform set_config('app.bypass_lock', 'off', true);
  return n;
end $$;
revoke execute on function store_daily_rates(jsonb) from public, anon, authenticated;
grant usage on schema public to service_role;
grant execute on function store_daily_rates(jsonb) to service_role;

-- conversions use the line's daily rate when it has one, else the month's Wise rate
drop view v_landed_cost;
drop view v_purchase_lines;

create view v_purchase_lines with (security_invoker = true) as
select pl.*,
       p.name   as product_name,
       p.agreed_courier_per_unit,
       c.name   as company_name,
       v.name   as vendor_name,
       v.kind   as vendor_kind,
       li.asin, li.fnsku, li.channel,
       s.box_no, s.amazon_shipment_id, s.tracking_no, s.status as shipment_status, s.received_on,
       coalesce(pl.fx_inr_per_gbp, fx.inr_per_gbp) as inr_per_gbp,
       case when pl.fx_inr_per_gbp is not null then 'daily' else 'monthly' end as fx_basis,
       (coalesce(pl.unit_price, 0) + pl.courier_per_unit) as landed_per_unit,
       case pl.currency when 'INR' then coalesce(pl.unit_price, 0) + pl.courier_per_unit
                        when 'GBP' then (coalesce(pl.unit_price, 0) + pl.courier_per_unit) * coalesce(pl.fx_inr_per_gbp, fx.inr_per_gbp) end
         as landed_per_unit_inr,
       case pl.currency when 'GBP' then coalesce(pl.unit_price, 0) + pl.courier_per_unit
                        when 'INR' then (coalesce(pl.unit_price, 0) + pl.courier_per_unit) / coalesce(pl.fx_inr_per_gbp, fx.inr_per_gbp) end
         as landed_per_unit_gbp,
       case when pl.received_qty > 0 then pl.line_total / pl.received_qty end as landed_per_received_unit,
       case pl.currency when 'INR' then pl.line_total when 'GBP' then pl.line_total * coalesce(pl.fx_inr_per_gbp, fx.inr_per_gbp) end as line_total_inr,
       case pl.currency when 'GBP' then pl.line_total when 'INR' then pl.line_total / coalesce(pl.fx_inr_per_gbp, fx.inr_per_gbp) end as line_total_gbp
  from purchase_lines pl
  join products p   on p.id = pl.product_id
  join companies c  on c.code = pl.company_code
  join vendors v    on v.id = pl.vendor_id
  left join listings li  on li.id = pl.listing_id
  left join shipments s  on s.id = pl.shipment_id
  left join v_fx fx      on fx.month = pl.period_month;

create view v_landed_cost with (security_invoker = true) as
select period_month, company_code, product_id, product_name, currency,
       sum(qty)                                   as qty,
       sum(received_qty)                          as received_qty,
       sum(line_total)                            as total_cost,
       round(sum(line_total) / nullif(sum(qty), 0), 2)            as landed_per_unit,
       round(sum(line_total_inr) / nullif(sum(qty), 0), 2)        as landed_per_unit_inr,
       round(sum(line_total_gbp) / nullif(sum(qty), 0), 4)        as landed_per_unit_gbp,
       round(sum(line_total) / nullif(sum(received_qty), 0), 2)   as landed_per_received_unit
  from v_purchase_lines
 group by period_month, company_code, product_id, product_name, currency;

grant select on v_purchase_lines, v_landed_cost to authenticated;

-- ===== supabase/migrations/20261126000010_companies_vat.sql
-- Company names and Default VAT (margin calculator file, 26 Nov 2026). Codes and all existing data are unchanged:
-- every other table refers to a company by its code, so only the display name, list order and a VAT setting change.

alter table companies
  add column sort_order      integer,
  add column default_vat_pct numeric(5, 2) not null default 0,
  add column vat_scheme      text;                       -- e.g. 'Flat Rate VAT'; null for 0% VAT

create function company_vat_rules() returns trigger language plpgsql as $$
begin
  if new.default_vat_pct < 0 or new.default_vat_pct > 100 then
    raise exception 'VAT must be between 0%% and 100%%.' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger b_company_vat before insert or update of default_vat_pct on companies
  for each row execute function company_vat_rules();

-- names, order and starting VAT (also set in seed.sql for new projects)
update companies c set name = v.name, sort_order = v.ord, default_vat_pct = v.vat, vat_scheme = v.scheme,
                       aliases = (select array_agg(distinct a) from unnest(c.aliases || v.extra) a)
  from (values ('CMR', 'Caemora Ltd',  1, 7.5, 'Flat Rate VAT', '{}'::text[]),
               ('ARC', 'ARC UK G Ltd', 2, 7.5, 'Flat Rate VAT', '{arc uk g ltd}'),
               ('YD',  'Youdent Ltd',  3, 0,   null,            '{youdent ltd}'),
               ('GOE', 'Goenche Ltd',  4, 0,   null,            '{}'),
               ('GOA', 'Goasales',     5, 0,   null,            '{goasales}'),
               ('GEN', 'Gentech',      6, 0,   null,            '{}'),
               ('ALS', 'Al Store',     7, 0,   null,            '{}')) v(code, name, ord, vat, scheme, extra)
 where c.code = v.code;

-- every change to a company (VAT included) goes into the change history; only an admin can make one (RLS admin_write)
create trigger z_audit after insert or update or delete on companies for each row execute function write_audit();

-- the one way the app changes VAT: admin only, with a clear refusal for anyone else
create function set_vat(p_code text, p_vat numeric, p_scheme text) returns void
language plpgsql set search_path = public as $$
begin
  if not is_admin() then raise exception 'Only an admin can change VAT.' using errcode = 'P0001'; end if;
  update companies set default_vat_pct = p_vat, vat_scheme = nullif(btrim(coalesce(p_scheme, '')), '') where code = p_code;
  if not found then raise exception 'Unknown company %.', p_code using errcode = 'P0001'; end if;
end $$;

-- VAT changes: old value, new value, who and when (admins only, like the rest of the change history)
create view v_company_vat_history with (security_invoker = true) as
select a.id, a.changed_at, a.row_key as code, c.name as company_name,
       (a.old_data ->> 'default_vat_pct')::numeric as old_vat, (a.new_data ->> 'default_vat_pct')::numeric as new_vat,
       a.old_data ->> 'vat_scheme' as old_scheme, a.new_data ->> 'vat_scheme' as new_scheme,
       a.changed_by, p.full_name as changed_by_name
  from audit_log a
  left join companies c on c.code = a.row_key
  left join profiles p on p.id = a.changed_by
 where a.table_name = 'companies' and a.action = 'UPDATE'
   and ((a.old_data ->> 'default_vat_pct') is distinct from (a.new_data ->> 'default_vat_pct')
        or (a.old_data ->> 'vat_scheme') is distinct from (a.new_data ->> 'vat_scheme'));
grant select on v_company_vat_history to authenticated;

-- ===== supabase/migrations/20261126000011_margins.sql
-- Margins (MRG-01..MRG-08): a separate section with its own data; it does not change purchases, shipments or payments.
-- Only inputs are stored. Every figure (landed cost, fees, tax, profit, ROI) is worked out from them, the current
-- settings and the company's VAT each time it is shown (lib/margin.ts), so a change to any of them updates every line.
-- Everyone signed in can read; only an admin can change anything.

create table margin_lines (
  id                     bigint generated always as identity primary key,
  channel                text not null check (channel in ('AMAZON', 'EBAY')),
  company_code           text not null references companies (code),
  product_id             bigint references products (id) on delete set null,
  name                   text not null check (btrim(name) <> ''),
  asin                   text,
  fnsku                  text,
  listing_status         text not null default 'listed' check (listing_status in ('listed', 'not_listed')),
  owner                  text,
  notes                  text,
  product_cost           numeric(12, 4) not null default 0 check (product_cost >= 0),
  product_cost_currency  currency_code not null default 'INR',
  courier_cost           numeric(12, 4) not null default 0 check (courier_cost >= 0),
  courier_currency       currency_code not null default 'INR',
  referral_pct           numeric(6, 3),        -- Amazon: % of the selling price
  fba_fee                numeric(10, 4),       -- Amazon: £ per unit
  promo_per_unit         numeric(10, 4),       -- Amazon: promo/ads £ per unit
  local_shipping         numeric(10, 4),       -- eBay: £ per order
  misc_expense           numeric(10, 4),       -- eBay: £ per order
  ad_pct                 numeric(6, 3),        -- eBay: ads as % of the selling price
  selling_price          numeric(10, 4) not null check (selling_price >= 0),
  tax_override_pct       numeric(5, 2) check (tax_override_pct between 0 and 100),   -- null = the company's Default VAT
  fx_rate                numeric(12, 4) check (fx_rate > 0),   -- ₹ per £, locked on the line (MRG-08)
  fx_rate_date           date,
  fx_source              text check (fx_source in ('daily', 'monthly', 'manual')),
  created_by             uuid references auth.users (id) default auth.uid(),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);
create index margin_lines_list_idx on margin_lines (channel, company_code);

-- MRG-08: a new line takes the day's rate (the latest published); a rate typed by hand is marked as such
create function margin_line_fx() returns trigger
language plpgsql security definer set search_path = public as $$
declare r daily_fx_rates; today date := (now() at time zone 'Europe/London')::date;
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' and new.fx_rate is not distinct from old.fx_rate then return new; end if;
  if new.fx_rate is null then
    r := daily_rate_for(today);
    if r.rate_date is not null then
      new.fx_rate := r.inr_per_gbp; new.fx_rate_date := r.rate_date; new.fx_source := 'daily';
    else
      new.fx_rate := (select inr_per_gbp from v_fx where month <= today order by month desc limit 1);
      new.fx_rate_date := today; new.fx_source := 'monthly';
    end if;
    if new.fx_rate is null then raise exception 'Enter an exchange rate (₹ per £).' using errcode = 'P0001'; end if;
  elsif new.fx_source is null or (tg_op = 'UPDATE' and new.fx_source is not distinct from old.fx_source) then
    new.fx_source := 'manual'; new.fx_rate_date := today;
  end if;
  return new;
end $$;
create trigger b_margin_line_fx before insert or update on margin_lines for each row execute function margin_line_fx();

alter table margin_lines enable row level security;
create policy read_all on margin_lines for select to authenticated using (is_active_user());
create policy admin_write on margin_lines for all to authenticated using (is_admin()) with check (is_admin());
grant select, insert, update, delete on margin_lines to authenticated;
create trigger z_audit after insert or update or delete on margin_lines for each row execute function write_audit();

-- MRG-01: the line's tax rate is its own, else its company's Default VAT
create view v_margin_lines with (security_invoker = true) as
select m.*, c.name as company_name, c.default_vat_pct as company_vat_pct,
       coalesce(m.tax_override_pct, c.default_vat_pct) as effective_tax_pct
  from margin_lines m join companies c on c.code = m.company_code;
grant select on v_margin_lines to authenticated;

-- MRG-08 AC4: "Use today's rate" (admin)
create function use_todays_rate(p_id bigint) returns void
language plpgsql set search_path = public as $$
declare r daily_fx_rates;
begin
  if not is_admin() then raise exception 'Only an admin can change margins.' using errcode = 'P0001'; end if;
  r := daily_rate_for((now() at time zone 'Europe/London')::date);
  if r.rate_date is null then raise exception 'No daily rate is available yet.' using errcode = 'P0001'; end if;
  update margin_lines set fx_rate = r.inr_per_gbp, fx_rate_date = r.rate_date, fx_source = 'daily' where id = p_id;
end $$;

-- MRG-07 AC4: copy a line to another company: same costs, the new company's tax (admin)
create function copy_margin_line(p_id bigint, p_company text) returns bigint
language plpgsql set search_path = public as $$
declare nid bigint;
begin
  if not is_admin() then raise exception 'Only an admin can change margins.' using errcode = 'P0001'; end if;
  insert into margin_lines (channel, company_code, product_id, name, asin, fnsku, listing_status, owner, notes, product_cost,
                            product_cost_currency, courier_cost, courier_currency, referral_pct, fba_fee, promo_per_unit,
                            local_shipping, misc_expense, ad_pct, selling_price, tax_override_pct, fx_rate, fx_rate_date, fx_source)
  select channel, p_company, product_id, name, asin, fnsku, listing_status, owner, notes, product_cost, product_cost_currency,
         courier_cost, courier_currency, referral_pct, fba_fee, promo_per_unit, local_shipping, misc_expense, ad_pct,
         selling_price, null, fx_rate, fx_rate_date, fx_source
    from margin_lines where id = p_id
  returning id into nid;
  if nid is null then raise exception 'Line not found.' using errcode = 'P0001'; end if;
  return nid;
end $$;

-- MRG-02: shared fees and the ROI target (settings: everyone reads, admin changes, every change kept)
insert into settings (key, value, description) values
  ('margin_fee_vat_pct',         '20',   'Margins: VAT on Amazon and eBay fees (%)'),
  ('margin_fba_surcharge_pct',   '2',    'Margins: Amazon FBA surcharge (% of the FBA fee)'),
  ('margin_dst_pct',             '2',    'Margins: Amazon Digital Services Tax (% of referral fee + FBA fee)'),
  ('margin_ebay_fee_pct',        '12.8', 'Margins: eBay fee (% of selling price)'),
  ('margin_ebay_fixed_fee',      '0.30', 'Margins: eBay fixed fee (£ per order)'),
  ('margin_ebay_local_shipping', '2.76', 'Margins: eBay local shipping default (£ per order)'),
  ('margin_ebay_misc',           '0.05', 'Margins: eBay miscellaneous expense default (£ per order)'),
  ('margin_roi_target_pct',      '25',   'Margins: ROI target (%)')
on conflict (key) do nothing;

-- MRG-05 AC3: price history
create view v_margin_price_history with (security_invoker = true) as
select a.id, a.row_key::bigint as line_id, a.changed_at,
       (a.old_data ->> 'selling_price')::numeric as old_price, (a.new_data ->> 'selling_price')::numeric as new_price,
       a.changed_by, p.full_name as changed_by_name
  from audit_log a left join profiles p on p.id = a.changed_by
 where a.table_name = 'margin_lines' and a.action = 'UPDATE'
   and (a.old_data ->> 'selling_price') is distinct from (a.new_data ->> 'selling_price');

-- MRG-02 AC4 (and other settings): old value, new value, who and when
create view v_settings_history with (security_invoker = true) as
select a.id, a.row_key as key, a.changed_at, a.old_data ->> 'value' as old_value, a.new_data ->> 'value' as new_value,
       a.changed_by, p.full_name as changed_by_name
  from audit_log a left join profiles p on p.id = a.changed_by
 where a.table_name = 'settings' and a.action = 'UPDATE' and (a.old_data -> 'value') is distinct from (a.new_data -> 'value');

grant select on v_margin_price_history, v_settings_history to authenticated;

-- ===== supabase/migrations/20261126000012_margin_platforms.sql
-- MRG-09: one line per product, compared across Amazon, eBay, Shopify, OnBuy and Etsy.
-- margin_products holds what is entered once (name, ASIN, FNSKU, costs, the locked rate); margin_lines becomes one row per
-- platform (price, company, that platform's own costs). Existing lines each become a product line of their own, keeping
-- their id, so nothing is merged here: likely matches are confirmed one by one by an admin (merge_margin_products).

create table margin_products (
  id                     bigint generated always as identity primary key,
  product_id             bigint references products (id) on delete set null,
  name                   text not null check (btrim(name) <> ''),
  asin                   text,
  fnsku                  text,
  owner                  text,
  notes                  text,
  product_cost           numeric(12, 4) not null default 0 check (product_cost >= 0),
  product_cost_currency  currency_code not null default 'INR',
  courier_cost           numeric(12, 4) not null default 0 check (courier_cost >= 0),
  courier_currency       currency_code not null default 'INR',
  fx_rate                numeric(12, 4) check (fx_rate > 0),
  fx_rate_date           date,
  fx_source              text check (fx_source in ('daily', 'monthly', 'manual')),
  created_by             uuid references auth.users (id) default auth.uid(),
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now()
);

-- each existing line becomes a product line with the same id (old links keep working)
insert into margin_products (id, product_id, name, asin, fnsku, owner, notes, product_cost, product_cost_currency, courier_cost,
                             courier_currency, fx_rate, fx_rate_date, fx_source, created_by, created_at, updated_at)
overriding system value
select id, product_id, name, asin, fnsku, owner, notes, product_cost, product_cost_currency, courier_cost, courier_currency,
       fx_rate, fx_rate_date, fx_source, created_by, created_at, updated_at
  from margin_lines;
select setval(pg_get_serial_sequence('margin_products', 'id'), greatest((select max(id) from margin_products), 1), (select count(*) > 0 from margin_products));

-- the locked rate (MRG-08) now lives on the product line
drop trigger b_margin_line_fx on margin_lines;
drop function margin_line_fx();
create function margin_product_fx() returns trigger
language plpgsql security definer set search_path = public as $$
declare r daily_fx_rates; today date := (now() at time zone 'Europe/London')::date;
begin
  new.updated_at := now();
  if tg_op = 'UPDATE' and new.fx_rate is not distinct from old.fx_rate then return new; end if;
  if new.fx_rate is null then
    r := daily_rate_for(today);
    if r.rate_date is not null then
      new.fx_rate := r.inr_per_gbp; new.fx_rate_date := r.rate_date; new.fx_source := 'daily';
    else
      new.fx_rate := (select inr_per_gbp from v_fx where month <= today order by month desc limit 1);
      new.fx_rate_date := today; new.fx_source := 'monthly';
    end if;
    if new.fx_rate is null then raise exception 'Enter an exchange rate (₹ per £).' using errcode = 'P0001'; end if;
  elsif new.fx_source is null or (tg_op = 'UPDATE' and new.fx_source is not distinct from old.fx_source) then
    new.fx_source := 'manual'; new.fx_rate_date := today;
  end if;
  return new;
end $$;
create trigger b_margin_product_fx before insert or update on margin_products for each row execute function margin_product_fx();

alter table margin_products enable row level security;
create policy read_all on margin_products for select to authenticated using (is_active_user());
create policy admin_write on margin_products for all to authenticated using (is_admin()) with check (is_admin());
grant select, insert, update, delete on margin_products to authenticated;
create trigger z_audit after insert or update or delete on margin_products for each row execute function write_audit();

-- margin_lines: one row per platform of a product line
drop view v_margin_lines;
drop function copy_margin_line(bigint, text);   -- replaced by choosing each platform's company (MRG-09 AC4)
alter table margin_lines add column margin_product_id bigint references margin_products (id) on delete cascade;
update margin_lines set margin_product_id = id;
alter table margin_lines
  alter column margin_product_id set not null,
  add column hidden boolean not null default false,        -- "not sold on this platform": left out of the comparison
  alter column selling_price drop not null,                 -- no price = "Not priced"
  drop constraint margin_lines_channel_check,
  add constraint margin_lines_channel_check check (channel in ('AMAZON', 'EBAY', 'SHOPIFY', 'ONBUY', 'ETSY')),
  add constraint margin_lines_one_per_platform unique (margin_product_id, channel),
  drop column product_id, drop column name, drop column asin, drop column fnsku, drop column owner, drop column notes,
  drop column product_cost, drop column product_cost_currency, drop column courier_cost, drop column courier_currency,
  drop column fx_rate, drop column fx_rate_date, drop column fx_source;
drop index if exists margin_lines_list_idx;
create index margin_lines_product_idx on margin_lines (margin_product_id);

create function margin_line_touch() returns trigger language plpgsql as $$
begin new.updated_at := now(); return new; end $$;
create trigger b_margin_line_touch before update on margin_lines for each row execute function margin_line_touch();

-- one row per platform, with its product line's inputs (same column names as before, so the calculations are unchanged)
create view v_margin_lines with (security_invoker = true) as
select m.id, m.margin_product_id, m.channel, m.company_code, m.listing_status, m.hidden,
       m.referral_pct, m.fba_fee, m.promo_per_unit, m.local_shipping, m.misc_expense, m.ad_pct, m.selling_price, m.tax_override_pct,
       p.product_id, p.name, p.asin, p.fnsku, p.owner, p.notes, p.product_cost, p.product_cost_currency, p.courier_cost, p.courier_currency,
       p.fx_rate, p.fx_rate_date, p.fx_source,
       c.name as company_name, c.default_vat_pct as company_vat_pct, coalesce(m.tax_override_pct, c.default_vat_pct) as effective_tax_pct,
       m.created_at, greatest(m.updated_at, p.updated_at) as updated_at
  from margin_lines m join margin_products p on p.id = m.margin_product_id join companies c on c.code = m.company_code;
grant select on v_margin_lines to authenticated;

-- MRG-08 AC4, now on the product line
drop function use_todays_rate(bigint);
create function use_todays_rate(p_product bigint) returns void
language plpgsql set search_path = public as $$
declare r daily_fx_rates;
begin
  if not is_admin() then raise exception 'Only an admin can change margins.' using errcode = 'P0001'; end if;
  r := daily_rate_for((now() at time zone 'Europe/London')::date);
  if r.rate_date is null then raise exception 'No daily rate is available yet.' using errcode = 'P0001'; end if;
  update margin_products set fx_rate = r.inr_per_gbp, fx_rate_date = r.rate_date, fx_source = 'daily' where id = p_product;
end $$;

-- Save a product line and its platforms in one go (admin; row-level security applies).
-- p: {id?, product_id, name, asin, fnsku, owner, notes, product_cost, product_cost_currency, courier_cost, courier_currency,
--     fx_rate, fx_source?, fx_rate_date?, platforms: [{channel, company_code, selling_price, tax_override_pct, hidden, listing_status,
--     referral_pct, fba_fee, promo_per_unit, local_shipping, misc_expense, ad_pct}]}
create function save_margin_product(p jsonb) returns bigint
language plpgsql set search_path = public as $$
declare pid bigint := nullif(p ->> 'id', '')::bigint; x jsonb; n int;
begin
  if not is_admin() then raise exception 'Only an admin can change margins.' using errcode = 'P0001'; end if;
  if pid is null then
    insert into margin_products (product_id, name, asin, fnsku, owner, notes, product_cost, product_cost_currency, courier_cost,
                                 courier_currency, fx_rate, fx_source, fx_rate_date)
    values ((p ->> 'product_id')::bigint, p ->> 'name', p ->> 'asin', p ->> 'fnsku', p ->> 'owner', p ->> 'notes',
            coalesce((p ->> 'product_cost')::numeric, 0), coalesce(p ->> 'product_cost_currency', 'INR')::currency_code,
            coalesce((p ->> 'courier_cost')::numeric, 0), coalesce(p ->> 'courier_currency', 'INR')::currency_code,
            (p ->> 'fx_rate')::numeric, nullif(p ->> 'fx_source', ''), nullif(p ->> 'fx_rate_date', '')::date)
    returning id into pid;
  else
    update margin_products set product_id = (p ->> 'product_id')::bigint, name = p ->> 'name', asin = p ->> 'asin', fnsku = p ->> 'fnsku',
           owner = p ->> 'owner', notes = p ->> 'notes',
           product_cost = coalesce((p ->> 'product_cost')::numeric, 0), product_cost_currency = coalesce(p ->> 'product_cost_currency', 'INR')::currency_code,
           courier_cost = coalesce((p ->> 'courier_cost')::numeric, 0), courier_currency = coalesce(p ->> 'courier_currency', 'INR')::currency_code,
           fx_rate = (p ->> 'fx_rate')::numeric
     where id = pid;
    get diagnostics n = row_count;
    if n = 0 then raise exception 'Line not found.' using errcode = 'P0001'; end if;
  end if;
  for x in select * from jsonb_array_elements(coalesce(p -> 'platforms', '[]')) loop
    if exists (select 1 from margin_lines where margin_product_id = pid and channel = x ->> 'channel') then
      update margin_lines set company_code = x ->> 'company_code', selling_price = (x ->> 'selling_price')::numeric,
             tax_override_pct = (x ->> 'tax_override_pct')::numeric, hidden = coalesce((x ->> 'hidden')::boolean, false),
             listing_status = coalesce(x ->> 'listing_status', 'listed'),
             referral_pct = (x ->> 'referral_pct')::numeric, fba_fee = (x ->> 'fba_fee')::numeric, promo_per_unit = (x ->> 'promo_per_unit')::numeric,
             local_shipping = (x ->> 'local_shipping')::numeric, misc_expense = (x ->> 'misc_expense')::numeric, ad_pct = (x ->> 'ad_pct')::numeric
       where margin_product_id = pid and channel = x ->> 'channel'
         and (company_code, selling_price, tax_override_pct, hidden, listing_status, referral_pct, fba_fee, promo_per_unit,
              local_shipping, misc_expense, ad_pct)
             is distinct from
             (x ->> 'company_code', (x ->> 'selling_price')::numeric, (x ->> 'tax_override_pct')::numeric, coalesce((x ->> 'hidden')::boolean, false),
              coalesce(x ->> 'listing_status', 'listed'), (x ->> 'referral_pct')::numeric, (x ->> 'fba_fee')::numeric, (x ->> 'promo_per_unit')::numeric,
              (x ->> 'local_shipping')::numeric, (x ->> 'misc_expense')::numeric, (x ->> 'ad_pct')::numeric);
    elsif (x ->> 'selling_price') is not null or coalesce((x ->> 'hidden')::boolean, false) then
      insert into margin_lines (margin_product_id, channel, company_code, selling_price, tax_override_pct, hidden, listing_status,
                                referral_pct, fba_fee, promo_per_unit, local_shipping, misc_expense, ad_pct)
      values (pid, x ->> 'channel', x ->> 'company_code', (x ->> 'selling_price')::numeric, (x ->> 'tax_override_pct')::numeric,
              coalesce((x ->> 'hidden')::boolean, false), coalesce(x ->> 'listing_status', 'listed'),
              (x ->> 'referral_pct')::numeric, (x ->> 'fba_fee')::numeric, (x ->> 'promo_per_unit')::numeric,
              (x ->> 'local_shipping')::numeric, (x ->> 'misc_expense')::numeric, (x ->> 'ad_pct')::numeric);
    end if;
  end loop;
  return pid;
end $$;

-- MRG-09 AC6: an admin confirms a match. p_keep's name, costs and rate stay; p_from's platforms (prices, fees and their
-- price history, which is kept by platform row) move onto it and p_from goes. Only lines on different platforms can merge.
create function merge_margin_products(p_keep bigint, p_from bigint) returns void
language plpgsql set search_path = public as $$
begin
  if not is_admin() then raise exception 'Only an admin can change margins.' using errcode = 'P0001'; end if;
  if p_keep = p_from then raise exception 'Choose two different lines.' using errcode = 'P0001'; end if;
  if (select count(*) from margin_products where id in (p_keep, p_from)) <> 2 then raise exception 'Line not found.' using errcode = 'P0001'; end if;
  if exists (select 1 from margin_lines a join margin_lines b using (channel) where a.margin_product_id = p_keep and b.margin_product_id = p_from) then
    raise exception 'Both lines have the same platform, so they cannot be merged.' using errcode = 'P0001';
  end if;
  update margin_products k set asin = coalesce(k.asin, f.asin), fnsku = coalesce(k.fnsku, f.fnsku), product_id = coalesce(k.product_id, f.product_id),
         notes = case when f.notes is null or f.notes = k.notes then k.notes when k.notes is null then f.notes else k.notes || E'\n' || f.notes end
    from margin_products f where k.id = p_keep and f.id = p_from;
  update margin_lines set margin_product_id = p_keep where margin_product_id = p_from;
  delete from margin_products where id = p_from;
  delete from margin_match_dismissed where p_from in (a_id, b_id);
end $$;

-- "Not a match": the pair is not suggested again
create table margin_match_dismissed (
  a_id bigint not null references margin_products (id) on delete cascade,
  b_id bigint not null references margin_products (id) on delete cascade,
  dismissed_by uuid references auth.users (id) default auth.uid(),
  dismissed_at timestamptz not null default now(),
  primary key (a_id, b_id), check (a_id < b_id)
);
alter table margin_match_dismissed enable row level security;
create policy read_all on margin_match_dismissed for select to authenticated using (is_active_user());
create policy admin_write on margin_match_dismissed for all to authenticated using (is_admin()) with check (is_admin());
grant select, insert, delete on margin_match_dismissed to authenticated;

-- price history per platform row (unchanged view, now with the platform and product line)
drop view v_margin_price_history;
create view v_margin_price_history with (security_invoker = true) as
select a.id, a.row_key::bigint as line_id, m.margin_product_id, m.channel, a.changed_at,
       (a.old_data ->> 'selling_price')::numeric as old_price, (a.new_data ->> 'selling_price')::numeric as new_price,
       a.changed_by, p.full_name as changed_by_name
  from audit_log a left join profiles p on p.id = a.changed_by left join margin_lines m on m.id = a.row_key::bigint
 where a.table_name = 'margin_lines' and a.action = 'UPDATE'
   and (a.old_data ->> 'selling_price') is distinct from (a.new_data ->> 'selling_price');
grant select on v_margin_price_history to authenticated;

-- Shopify, OnBuy and Etsy fees (MRG-09 "Margin settings to add"): 0 until the real fees are entered
insert into settings (key, value, description)
select 'margin_' || pl.k || '_' || s.k, s.v::jsonb, 'Margins: ' || pl.label || ' ' || s.label
  from (values ('shopify', 'Shopify', 1), ('onbuy', 'OnBuy', 2), ('etsy', 'Etsy', 3)) pl (k, label, o),
       (values ('fee_pct', '0', 'platform fee (% of selling price)'), ('fixed_fee', '0', 'fixed fee (£ per order or listing)'),
               ('payment_pct', '0', 'payment processing fee (% of selling price)'), ('payment_fixed', '0', 'payment processing fee (£ per order)'),
               ('fee_vat_pct', '0', 'VAT on platform fees (%)'), ('shipping', '2.76', 'default shipping (£ per order)'),
               ('misc', '0.05', 'default miscellaneous (£ per order)')) s (k, v, label)
on conflict (key) do nothing;

-- ===== supabase/migrations/20261127000013_audit_log.sql
-- Audit log screen (27 Nov 2026): admins see who changed what, plus sign-ins, sign-outs and failed sign-ins.
-- Changes were already recorded in audit_log by write_audit(); this adds the few areas that were not, sign-in events,
-- a readable view, and makes the log impossible to alter. Viewing pages records nothing.

-- AUD AC7: nobody can change or remove log entries through the app, admins included (only the database's own triggers write)
revoke insert, update, delete, truncate on audit_log from anon, authenticated;

-- AUD AC6: suppliers and "Not a match"
create trigger z_audit after insert or update or delete on vendors for each row execute function write_audit();
create trigger z_audit after insert or delete on margin_match_dismissed for each row execute function write_audit();

-- AUD AC6: a flag acknowledged or resolved by a person (automatic checks and the bulk "mark as seen" are left out here)
create trigger z_audit after update on flags for each row
  when (old.status is distinct from new.status
        and (new.status = 'acknowledged' or (new.status = 'resolved' and new.resolved_by is not null))
        and auth.uid() is not null
        and coalesce(current_setting('app.bulk_ack', true), '') <> 'on')
  execute function write_audit();

-- bulk "mark as seen" (Admin page): one entry for the lot, not one per flag. Otherwise unchanged.
create or replace function acknowledge_flags_before(p_month date, p_rule text default null) returns integer
language plpgsql security definer set search_path = public as $$
declare n integer;
begin
  if not is_admin() then raise exception 'Only an admin can do this.' using errcode = 'P0001'; end if;
  perform set_config('app.bulk_ack', 'on', true);
  update flags set status = 'acknowledged', updated_at = now()
   where status = 'open' and period_month < p_month and (p_rule is null or rule = p_rule);
  get diagnostics n = row_count;
  perform set_config('app.bulk_ack', '', true);
  if n > 0 then
    insert into audit_log (table_name, row_key, action, old_data, new_data, changed_by)
    values ('flags', null, 'BULK', null, jsonb_build_object('count', n, 'before', p_month, 'rule', p_rule), auth.uid());
  end if;
  return n;
end $$;

-- AUD AC4: sign-in events. Signed in / signed out need a session and record the person's own email;
-- a failed attempt has no session and records the email typed (at most 20 per email, and 300 in all, per 10 minutes).
create function record_sign_in_event(p_event text, p_email text) returns void
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); em text;
begin
  if p_event in ('SIGN_IN', 'SIGN_OUT') then
    if uid is null then raise exception 'Only someone signed in can record this.' using errcode = 'P0001'; end if;
    select email into em from profiles where id = uid;
    insert into audit_log (table_name, row_key, action, new_data, changed_by) values ('auth', uid::text, p_event, jsonb_build_object('email', em), uid);
  elsif p_event = 'SIGN_IN_FAILED' then
    em := lower(left(btrim(coalesce(p_email, '')), 200));
    if (select count(*) from audit_log where action = 'SIGN_IN_FAILED' and changed_at > now() - interval '10 minutes' and new_data ->> 'email' = em) >= 20
       or (select count(*) from audit_log where action = 'SIGN_IN_FAILED' and changed_at > now() - interval '10 minutes') >= 300 then
      return;
    end if;
    insert into audit_log (table_name, row_key, action, new_data, changed_by) values ('auth', null, 'SIGN_IN_FAILED', jsonb_build_object('email', em), null);
  else
    raise exception 'Unknown event.' using errcode = 'P0001';
  end if;
end $$;
revoke all on function record_sign_in_event(text, text) from public;
grant execute on function record_sign_in_event(text, text) to anon, authenticated;

create index if not exists audit_log_changed_at_idx on audit_log (changed_at desc);
create index if not exists audit_log_by_idx on audit_log (changed_by, changed_at desc);
create index if not exists audit_log_table_idx on audit_log (table_name, changed_at desc);

-- AUD AC1/AC2: the log with the person's name (admins only: audit_log can only be read by an admin)
create view v_audit_log with (security_invoker = true) as
select a.id, a.changed_at, a.table_name, a.row_key, a.action, a.old_data, a.new_data, a.reason, a.period_month,
       a.changed_by, p.full_name as changed_by_name, p.email as changed_by_email
  from audit_log a left join profiles p on p.id = a.changed_by;
grant select on v_audit_log to authenticated;

-- ===== supabase/migrations/20261127000014_cases.sql
-- FLG-03 (27 Nov 2026): every flag that needs action becomes a case with an owner, a status and a due date.
-- Only flags raised from now on create cases (existing open flags do not). Access rules hold: the India team is never
-- given, and never sees, a case about payments or anything else outside purchases and shipments.

create type case_status as enum ('open', 'in_progress', 'resolved');

-- the admin's rules: which flag types create cases, and who gets them
create table case_rules (
  rule          text primary key,
  label         text not null,
  creates_case  boolean not null default false,
  assign_to     text not null default 'person' check (assign_to in ('entered_by', 'person')),
  assignee      uuid references profiles (id) on delete set null,   -- 'person': this person (none = the admin)
  staff_ok      boolean not null default true,                       -- false = money: only an admin may be given it
  updated_at    timestamptz not null default now()
);
insert into case_rules (rule, label, creates_case, assign_to, staff_ok) values
  ('missing_invoice_no',       'No invoice number',            true,  'entered_by', true),
  ('missing_invoice_date',     'No invoice date',              true,  'entered_by', true),
  ('blank_price',              'No price',                     true,  'entered_by', true),
  ('courier_above_rate_card',  'Courier above rate card',      true,  'entered_by', true),
  ('check_with_supplier',      'Check with supplier',          true,  'person',     true),
  ('raise_amazon_case',        'Raise Amazon case',            true,  'person',     true),
  ('price_change',             'Price changed',                false, 'entered_by', true),
  ('courier_change',           'Courier changed',              false, 'entered_by', true),
  ('courier_above_price',      'Courier > product price',      false, 'entered_by', true),
  ('suspect_currency',         'Looks like £ entered as ₹',    false, 'entered_by', true),
  ('receipt_discrepancy',      'Short/defective, no remark',   false, 'entered_by', true),
  ('long_in_transit',          'In transit too long',          false, 'entered_by', true),
  ('duplicate_tracking',       'Duplicate tracking no.',       false, 'entered_by', true),
  ('unconfirmed_payment',      'Unconfirmed payment',          false, 'person',     false),
  ('payment_missing_reference','Payment without reference',    false, 'person',     false),
  ('settled_month_edit',       'Edit to settled month',        false, 'person',     false);

insert into settings (key, value, description) values
  ('case_due_working_days', '3', 'Cases: due after this many working days (Mon–Fri)')
on conflict (key) do nothing;

create table cases (
  id               bigint generated always as identity primary key,
  flag_id          bigint references flags (id) on delete set null,
  rule             text not null,
  entity_type      text not null,
  entity_id        bigint not null,
  title            text not null,
  staff_ok         boolean not null default true,
  assigned_to      uuid references profiles (id),
  status           case_status not null default 'open',
  due_on           date not null,
  external_ref     text,                 -- e.g. the Amazon case ID (SHP-08 AC4)
  outcome          text check (outcome in ('units_found', 'replacement_sent', 'supplier_credit_note', 'amazon_reimbursed')),
  outcome_gbp      numeric(12, 2) check (outcome_gbp >= 0),
  resolution       text check (resolution in ('fix', 'owner', 'outcome')),
  resolution_note  text,
  resolved_by      uuid references profiles (id),
  resolved_at      timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);
create unique index cases_one_open_per_flag on cases (flag_id) where status <> 'resolved';
create index cases_assigned_idx on cases (assigned_to, status);

create table case_events (
  id         bigint generated always as identity primary key,
  case_id    bigint not null references cases (id) on delete cascade,
  at         timestamptz not null default now(),
  by         uuid,
  kind       text not null,             -- created, reassigned, status, reference, resolved, reopened, outcome
  from_user  uuid,
  to_user    uuid,
  note       text
);
create index case_events_case_idx on case_events (case_id, at);

-- Mon–Fri working days (UK bank holidays are not skipped)
create function add_working_days(p_from date, p_days integer) returns date language plpgsql immutable as $$
declare d date := p_from; n integer := 0;
begin
  while n < greatest(p_days, 0) loop
    d := d + 1;
    if extract(isodow from d) < 6 then n := n + 1; end if;
  end loop;
  return d;
end $$;

create function london_today() returns date language sql stable as $$ select (now() at time zone 'Europe/London')::date $$;

-- someone who may be given a case: active admin, or active India team member when the case is not about money
create function can_take_case(p_user uuid, p_staff_ok boolean) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from profiles where id = p_user and active and (role = 'admin' or (p_staff_ok and role = 'data_entry')))
$$;
create function default_case_admin() returns uuid language sql stable security definer set search_path = public as $$
  select id from profiles where role = 'admin' and active order by created_at, id limit 1
$$;

-- the India team only handles purchases and shipments
create function entity_staff_ok(p_entity text) returns boolean language sql immutable as $$
  select p_entity in ('purchase_lines', 'shipments', 'shipment_items')
$$;

create function case_rule_checks() returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.updated_at := now();
  if new.assignee is not null and not can_take_case(new.assignee, new.staff_ok) then
    raise exception '%', case when new.staff_ok then 'Choose an active admin or India team member.'
                              else 'Cases about payments and money can only go to an admin.' end using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger b_case_rule_checks before insert or update on case_rules for each row execute function case_rule_checks();

-- who a new case goes to
create function case_assignee(p_rule case_rules, p_entity text, p_id bigint) returns uuid
language plpgsql stable security definer set search_path = public as $$
declare who uuid; ok boolean := p_rule.staff_ok and entity_staff_ok(p_entity);
begin
  if p_rule.assign_to = 'entered_by' then
    execute format('select created_by from %I where id = $1', p_entity) into who using p_id;
  else
    who := p_rule.assignee;
  end if;
  if who is null or not can_take_case(who, ok) then who := default_case_admin(); end if;
  return who;
end $$;

-- open a case for a flag (when its rule creates cases and it has no open case yet)
create function open_case_for_flag(f flags) returns void
language plpgsql security definer set search_path = public as $$
declare r case_rules; who uuid; cid bigint;
begin
  if flag_on('no_cases') then return; end if;   -- set while flags for older problems are first raised
  select * into r from case_rules where rule = f.rule;
  if not found or not r.creates_case then return; end if;
  if exists (select 1 from cases where flag_id = f.id and status <> 'resolved') then return; end if;
  if f.entity_type not in ('purchase_lines', 'shipments', 'shipment_items', 'payments') then return; end if;
  who := case_assignee(r, f.entity_type, f.entity_id);
  insert into cases (flag_id, rule, entity_type, entity_id, title, staff_ok, assigned_to, due_on)
  values (f.id, f.rule, f.entity_type, f.entity_id, f.message, r.staff_ok and entity_staff_ok(f.entity_type), who,
          add_working_days(london_today(), setting_num('case_due_working_days', 3)::int))
  returning id into cid;
  insert into case_events (case_id, by, kind, to_user, note) values (cid, auth.uid(), 'created', who, 'Raised by the "' || r.label || '" flag');
end $$;

-- flags drive cases: a new or re-opened flag opens a case; a cleared flag closes it ("Resolved by fix"); a changed message updates the title
create function flags_to_cases() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'open' and (tg_op = 'INSERT' or old.status <> 'open') then
    perform open_case_for_flag(new);
  elsif tg_op = 'UPDATE' and new.status = 'resolved' and old.status <> 'resolved' then
    with done as (
      update cases set status = 'resolved', resolution = 'fix', resolved_at = now(), updated_at = now(),
                       resolution_note = coalesce(new.resolution_note, 'The problem was fixed')
       where flag_id = new.id and status <> 'resolved' returning id)
    insert into case_events (case_id, by, kind, note) select id, auth.uid(), 'resolved', 'Resolved by fix' from done;
  end if;
  if tg_op = 'UPDATE' and new.message is distinct from old.message then
    update cases set title = new.message, updated_at = now() where flag_id = new.id and status <> 'resolved';
  end if;
  return null;
end $$;
create trigger y_flags_to_cases after insert or update on flags for each row execute function flags_to_cases();

-- ---------------------------------------------------------------- actions (all checks here; no direct writes)

create function case_for_actor(p_case bigint) returns cases
language plpgsql stable security definer set search_path = public as $$
declare c cases;
begin
  select * into c from cases where id = p_case;
  if not found then raise exception 'Case not found.' using errcode = 'P0001'; end if;
  if not (is_admin() or (c.assigned_to = auth.uid() and is_staff() and c.staff_ok)) then
    raise exception 'This case is not assigned to you.' using errcode = 'P0001';
  end if;
  return c;
end $$;

create function reassign_case(p_case bigint, p_to uuid, p_note text) returns void
language plpgsql security definer set search_path = public as $$
declare c cases;
begin
  if not is_admin() then raise exception 'Only an admin can reassign a case.' using errcode = 'P0001'; end if;
  select * into c from cases where id = p_case;
  if not found then raise exception 'Case not found.' using errcode = 'P0001'; end if;
  if not can_take_case(p_to, c.staff_ok) then
    raise exception '%', case when c.staff_ok then 'Choose an active admin or India team member.'
                              else 'This case is about payments or money, so it can only go to an admin.' end using errcode = 'P0001';
  end if;
  update cases set assigned_to = p_to, updated_at = now() where id = p_case;
  insert into case_events (case_id, by, kind, from_user, to_user, note) values (p_case, auth.uid(), 'reassigned', c.assigned_to, p_to, nullif(btrim(coalesce(p_note, '')), ''));
end $$;

create function set_case_status(p_case bigint, p_status case_status) returns void
language plpgsql security definer set search_path = public as $$
declare c cases := case_for_actor(p_case);
begin
  if p_status = 'resolved' then raise exception 'Use Resolve, with a note.' using errcode = 'P0001'; end if;
  update cases set status = p_status, updated_at = now(), resolution = null, resolution_note = null, resolved_by = null, resolved_at = null where id = p_case;
  insert into case_events (case_id, by, kind, note) values (p_case, auth.uid(), case when c.status = 'resolved' then 'reopened' else 'status' end,
    case p_status when 'in_progress' then 'In progress' else 'Open' end);
end $$;

create function resolve_case(p_case bigint, p_note text) returns void
language plpgsql security definer set search_path = public as $$
declare c cases := case_for_actor(p_case);
begin
  if nullif(btrim(coalesce(p_note, '')), '') is null then raise exception 'Add a note saying what was done.' using errcode = 'P0001'; end if;
  if c.status = 'resolved' then raise exception 'This case is already resolved.' using errcode = 'P0001'; end if;
  update cases set status = 'resolved', resolution = 'owner', resolution_note = btrim(p_note), resolved_by = auth.uid(), resolved_at = now(), updated_at = now()
   where id = p_case;
  insert into case_events (case_id, by, kind, note) values (p_case, auth.uid(), 'resolved', btrim(p_note));
end $$;

-- ---------------------------------------------------------------- reading

alter table case_rules enable row level security;
create policy read_all on case_rules for select to authenticated using (is_active_user());
create policy admin_write on case_rules for update to authenticated using (is_admin()) with check (is_admin());
revoke insert, delete, truncate on case_rules from authenticated, anon;
create trigger z_audit after update on case_rules for each row execute function write_audit();

alter table cases enable row level security;
alter table case_events enable row level security;
-- admin and viewer: every case; India team: only their own, and never money
create policy read_cases on cases for select to authenticated
  using (can_view_money() or (is_staff() and assigned_to = auth.uid() and staff_ok));
create policy read_events on case_events for select to authenticated
  using (exists (select 1 from cases c where c.id = case_id));
revoke insert, update, delete, truncate on cases, case_events from authenticated, anon;
grant select on cases, case_events to authenticated;

-- colleagues' names (the India team cannot read other profiles; a name is all that is shown)
create function person_name(p_user uuid) returns text language sql stable security definer set search_path = public as $$
  select full_name from profiles where id = p_user and is_active_user()
$$;

create view v_cases with (security_invoker = true) as
select c.*, r.label as rule_label, person_name(c.assigned_to) as assigned_name,
       (c.status <> 'resolved' and c.due_on < london_today()) as overdue,
       case c.entity_type
         when 'purchase_lines' then '/purchases/' || c.entity_id
         when 'shipments' then '/shipments/' || c.entity_id
         when 'shipment_items' then '/shipments/' || (select i.shipment_id from shipment_items i where i.id = c.entity_id)
         when 'payments' then '/reconciliation'
         else '/flags' end as link
  from cases c left join case_rules r on r.rule = c.rule;
create view v_my_cases with (security_invoker = true) as
select * from v_cases where assigned_to = auth.uid() and status <> 'resolved';
create view v_case_events with (security_invoker = true) as
select e.*, person_name(e.by) as by_name, person_name(e.from_user) as from_name, person_name(e.to_user) as to_name
  from case_events e;
grant select on v_cases, v_my_cases, v_case_events to authenticated;

-- ===== supabase/migrations/20261127000015_receiving.sql
-- SHP-08 (27 Nov 2026): record what each box delivered, at home or at Amazon, and act on shortages.
-- Received counts (short and defective) stay open to admins and the India team at any time, settled months included
-- (as SHP-03 already allowed). Prices, quantities bought and companies stay locked as before.
-- "Received" = units that arrived, defective ones included; short = sent − received; defective is entered separately.

-- ---------------------------------------------------------------- destination
alter table shipments add column destination text check (destination in ('amazon', 'home'));
-- filled in quietly: no "updated" time, flag re-check or audit entry for the 275 existing boxes
alter table shipments disable trigger user;
update shipments set destination = case when upper(coalesce(amazon_shipment_id, '')) like 'FBA%' then 'amazon' else 'home' end;
alter table shipments enable trigger user;
alter table shipments alter column destination set not null;

create function shipment_destination() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    if new.destination is null then
      new.destination := case when upper(coalesce(new.amazon_shipment_id, '')) like 'FBA%' then 'amazon' else 'home' end;
    end if;
  elsif new.destination is distinct from old.destination and not is_admin() and not is_system() then
    raise exception 'Only an admin can change where a box goes.' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger a0_shipment_destination before insert or update on shipments for each row execute function shipment_destination();

-- an admin may correct the destination of a box from a settled month (it is not a money change)
create or replace function receipt_columns(p_table text) returns text[] language sql immutable as $$
  select case p_table
    when 'shipments' then array['status', 'received_on', 'received_by', 'tracking_no', 'courier', 'notes', 'updated_at', 'destination']
    -- generated totals are listed too: they are not yet computed in a BEFORE trigger, and follow from the other columns
    when 'purchase_lines' then array['defective_qty', 'short_qty', 'received_qty', 'checked_by', 'remarks', 'remarks_2',
                                     'amazon_case_id', 'reimbursement_id', 'reimbursed_gbp', 'updated_at', 'updated_by',
                                     'courier_total', 'goods_total', 'line_total', 'shipment_id']
    else array[]::text[] end
$$;

-- ---------------------------------------------------------------- counts on each box line
alter table shipment_items
  add column counted_by     uuid references profiles (id),
  add column counted_at     timestamptz,
  add column amazon_case_id text,
  add column outcome        text check (outcome in ('units_found', 'replacement_sent', 'supplier_credit_note', 'amazon_reimbursed')),
  add column outcome_gbp    numeric(12, 2) check (outcome_gbp >= 0),
  add column outcome_note   text,
  add column outcome_by     uuid references profiles (id),
  add column outcome_at     timestamptz;

-- history of counts (who changed received or defective, from what to what); readable by everyone signed in
create table receipt_counts (
  id             bigint generated always as identity primary key,
  item_id        bigint not null references shipment_items (id) on delete cascade,
  shipment_id    bigint not null,
  at             timestamptz not null default now(),
  by             uuid,
  old_received   integer, new_received integer,
  old_defective  integer, new_defective integer
);
create index receipt_counts_item_idx on receipt_counts (item_id, at);

create function item_counts() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'UPDATE' and (new.short_qty, new.defective_qty) is not distinct from (old.short_qty, old.defective_qty) then return new; end if;
  if new.short_qty > new.qty then
    raise exception 'Received cannot be more than the % sent.', new.qty using errcode = 'P0001';
  end if;
  if new.defective_qty > new.qty - new.short_qty then
    raise exception 'Defective (%) cannot be more than the % received.', new.defective_qty, new.qty - new.short_qty using errcode = 'P0001';
  end if;
  if tg_op = 'UPDATE' then
    new.counted_by := coalesce(auth.uid(), new.counted_by);
    new.counted_at := now();
    -- a recount replaces the old shortage: a new shortage is followed up afresh
    if new.outcome is not null and (new.short_qty > old.short_qty or new.defective_qty > old.defective_qty) then
      new.outcome := null; new.outcome_gbp := null; new.outcome_note := null; new.outcome_by := null; new.outcome_at := null;
    end if;
  end if;
  return new;
end $$;
create trigger b_item_counts before insert or update on shipment_items for each row execute function item_counts();

create function item_count_history() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (new.short_qty, new.defective_qty) is distinct from (old.short_qty, old.defective_qty) and not is_importing() then
    insert into receipt_counts (item_id, shipment_id, by, old_received, new_received, old_defective, new_defective)
    values (new.id, new.shipment_id, auth.uid(), old.qty - old.short_qty, new.qty - new.short_qty, old.defective_qty, new.defective_qty);
  end if;
  return null;
end $$;
create trigger x_item_count_history after update on shipment_items for each row execute function item_count_history();

alter table receipt_counts enable row level security;
create policy read_all on receipt_counts for select to authenticated using (is_active_user());
revoke insert, update, delete, truncate on receipt_counts from authenticated, anon;
grant select on receipt_counts to authenticated;
create view v_receipt_history with (security_invoker = true) as
select r.*, person_name(r.by) as by_name from receipt_counts r;
grant select on v_receipt_history to authenticated;

-- ---------------------------------------------------------------- shortage flags → cases (FLG-03)
-- Amazon box: "Raise Amazon case: 2 short, ENO Regular 30's, FBA15MRYZWHR"
-- Home box:   "Check with supplier: 2 short, Colgate dental floss 50m, box 7, invoice PE-140"
create function refresh_item_flags(p_item bigint) returns void
language plpgsql security definer set search_path = public as $$
declare i record; what text; active boolean; rule_on text; rule_off text; msg text;
begin
  select si.*, s.destination, s.box_no, s.amazon_shipment_id, pl.invoice_no, pl.company_code, pl.period_month, p.name as product_name
    into i
    from shipment_items si join shipments s on s.id = si.shipment_id
    join purchase_lines pl on pl.id = si.purchase_line_id join products p on p.id = pl.product_id
   where si.id = p_item;
  if not found then
    update flags set status = 'resolved', resolved_at = now(), resolution_note = 'Box line removed', updated_at = now()
     where entity_type = 'shipment_items' and entity_id = p_item and status <> 'resolved';
    return;
  end if;
  what := concat_ws(', ', case when i.short_qty > 0 then i.short_qty || ' short' end, case when i.defective_qty > 0 then i.defective_qty || ' defective' end);
  active := (i.short_qty > 0 or i.defective_qty > 0) and i.outcome is null;
  if i.destination = 'amazon' then
    rule_on := 'raise_amazon_case'; rule_off := 'check_with_supplier';
    msg := format('Raise Amazon case: %s, %s, %s', what, i.product_name, coalesce(i.amazon_shipment_id, 'box ' || coalesce(i.box_no, '#' || i.shipment_id)));
  else
    rule_on := 'check_with_supplier'; rule_off := 'raise_amazon_case';
    msg := format('Check with supplier: %s, %s, box %s, invoice %s', what, i.product_name, coalesce(i.box_no, '#' || i.shipment_id), coalesce(i.invoice_no, 'none'));
  end if;
  perform set_flag(rule_off, 'warning', 'shipment_items', p_item, i.period_month, i.company_code, false, '');
  perform set_flag(rule_on, 'warning', 'shipment_items', p_item, i.period_month, i.company_code, active, msg,
                   jsonb_build_object('shipment_id', i.shipment_id, 'purchase_line_id', i.purchase_line_id, 'short', i.short_qty, 'defective', i.defective_qty));
end $$;

create function item_flags_on_change() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if is_importing() then return null; end if;
  if tg_op = 'DELETE' then perform refresh_item_flags(old.id);
  elsif tg_op = 'INSERT' or (new.short_qty, new.defective_qty, new.outcome) is distinct from (old.short_qty, old.defective_qty, old.outcome) then
    perform refresh_item_flags(new.id);
  end if;
  return null;
end $$;
create trigger y_item_flags after insert or update or delete on shipment_items for each row execute function item_flags_on_change();

create function box_flags_on_change() returns trigger
language plpgsql security definer set search_path = public as $$
declare r record;
begin
  if new.destination is distinct from old.destination or new.box_no is distinct from old.box_no
     or new.amazon_shipment_id is distinct from old.amazon_shipment_id then
    for r in select id from shipment_items where shipment_id = new.id loop perform refresh_item_flags(r.id); end loop;
  end if;
  return null;
end $$;
create trigger y_box_item_flags after update on shipments for each row execute function box_flags_on_change();

-- the nightly check covers box lines too (otherwise unchanged)
create or replace function refresh_all_flags() returns integer
language plpgsql security definer set search_path = public as $$
declare r record; n integer := 0;
begin
  for r in select id from purchase_lines loop perform refresh_line_flags(r.id); n := n + 1; end loop;
  for r in select id from shipments      loop perform refresh_shipment_flags(r.id); end loop;
  for r in select id from payments       loop perform refresh_payment_flags(r.id); end loop;
  for r in select id from shipment_items where short_qty > 0 or defective_qty > 0 or outcome is not null loop perform refresh_item_flags(r.id); end loop;
  return n;
end $$;

-- boxes that were already short or defective get their flag now, without a case (only new problems become cases)
do $$
declare r record;
begin
  perform set_config('app.no_cases', 'on', true);
  for r in select id from shipment_items where short_qty > 0 or defective_qty > 0 loop perform refresh_item_flags(r.id); end loop;
  perform set_config('app.no_cases', '', true);
end $$;

-- the India team sees flags on box lines too (they are about shipments)
drop policy read_flags on flags;
create policy read_flags on flags for select to authenticated
  using (can_view_money() or (is_staff() and entity_type in ('purchase_lines', 'shipments', 'shipment_items')));

-- ---------------------------------------------------------------- case actions for shortages

-- SHP-08 AC4: the Amazon case ID → "Case raised with Amazon" (kept on the box line, where SHP-05 will read it)
create function set_case_reference(p_case bigint, p_ref text) returns void
language plpgsql security definer set search_path = public as $$
declare c cases := case_for_actor(p_case); ref text := nullif(btrim(coalesce(p_ref, '')), '');
begin
  if ref is null then raise exception 'Enter the case ID.' using errcode = 'P0001'; end if;
  update cases set external_ref = ref, status = case when status = 'open' then 'in_progress'::case_status else status end, updated_at = now() where id = p_case;
  if c.entity_type = 'shipment_items' and c.rule = 'raise_amazon_case' then
    update shipment_items set amazon_case_id = ref where id = c.entity_id;
  end if;
  insert into case_events (case_id, by, kind, note) values (p_case, auth.uid(), 'reference',
    case when c.rule = 'raise_amazon_case' then 'Case raised with Amazon: ' else 'Reference: ' end || ref);
end $$;

-- SHP-08 AC5: the outcome closes the case and shows on the box
create function resolve_shortage(p_case bigint, p_outcome text, p_gbp numeric, p_note text) returns void
language plpgsql security definer set search_path = public as $$
declare c cases := case_for_actor(p_case); label text;
begin
  if c.entity_type <> 'shipment_items' then raise exception 'This is not a shortage case.' using errcode = 'P0001'; end if;
  if c.status = 'resolved' then raise exception 'This case is already resolved.' using errcode = 'P0001'; end if;
  label := case p_outcome when 'units_found' then 'Units found' when 'replacement_sent' then 'Replacement sent'
                          when 'supplier_credit_note' then 'Supplier credit note' when 'amazon_reimbursed' then 'Amazon reimbursed' end;
  if label is null then raise exception 'Choose what happened.' using errcode = 'P0001'; end if;
  if p_outcome = 'amazon_reimbursed' and coalesce(p_gbp, 0) <= 0 then
    raise exception 'Enter the £ amount Amazon reimbursed.' using errcode = 'P0001';
  end if;
  -- close the case first, so clearing the flag below does not also mark it "Resolved by fix"
  update cases set status = 'resolved', resolution = 'outcome', outcome = p_outcome, outcome_gbp = p_gbp,
                   resolution_note = nullif(btrim(coalesce(p_note, '')), ''), resolved_by = auth.uid(), resolved_at = now(), updated_at = now()
   where id = p_case;
  insert into case_events (case_id, by, kind, note) values (p_case, auth.uid(), 'outcome',
    label || coalesce(' £' || to_char(p_gbp, 'FM999,990.00'), '') || coalesce(': ' || nullif(btrim(coalesce(p_note, '')), ''), ''));
  update shipment_items set outcome = p_outcome, outcome_gbp = p_gbp, outcome_note = nullif(btrim(coalesce(p_note, '')), ''),
                            outcome_by = auth.uid(), outcome_at = now()
   where id = c.entity_id;
end $$;

-- box contents with counts and shortage follow-up (the screen reads this)
create or replace view v_box_receipts with (security_invoker = true) as
select si.id, si.shipment_id, si.purchase_line_id, si.qty, si.short_qty, si.defective_qty, si.qty - si.short_qty as received,
       si.counted_at, person_name(si.counted_by) as counted_by_name, si.amazon_case_id, si.outcome, si.outcome_gbp, si.outcome_note, si.outcome_at,
       person_name(si.outcome_by) as outcome_by_name
  from shipment_items si;
grant select on v_box_receipts to authenticated;

-- ===== supabase/migrations/20261127000016_company_sales.sql
-- DSH-04 (27 Nov 2026): each company's monthly sales (£, including VAT, all platforms together), typed in by an admin for now.
-- A later sales sync (Amazon, eBay…) can fill the same table. Everyone signed in can see it; only an admin changes it.

create table company_sales (
  id            bigint generated always as identity primary key,
  company_code  text not null references companies (code),
  month         date not null,
  amount_gbp    numeric(14, 2) not null check (amount_gbp >= 0),
  updated_by    uuid references profiles (id) default auth.uid(),
  updated_at    timestamptz not null default now(),
  unique (company_code, month)
);

create function company_sales_month() returns trigger language plpgsql as $$
begin
  new.month := date_trunc('month', new.month)::date;
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  return new;
end $$;
create trigger b_company_sales_month before insert or update on company_sales for each row execute function company_sales_month();

alter table company_sales enable row level security;
create policy read_all on company_sales for select to authenticated using (is_active_user());
create policy admin_write on company_sales for all to authenticated using (is_admin()) with check (is_admin());
grant select, insert, update, delete on company_sales to authenticated;
create trigger z_audit after insert or update or delete on company_sales for each row execute function write_audit();

-- ===== supabase/migrations/20261128000017_dashboard_origin.sql
-- DSH-06 (28 Nov 2026): per month, units ordered with goods and courier paid, split by where the supplier is:
-- India (Indian suppliers, in ₹) and China (Chinese suppliers, in £). Stock only, as the units chart. Everyone can see it.
create function dashboard_by_origin(p_months integer default 12, p_end date default null)
returns table (month date, origin text, units bigint, goods numeric, courier numeric)
language sql stable security invoker set search_path = public as $$
  with bounds as (
    select date_trunc('month', coalesce(p_end, (now() at time zone 'Europe/London')::date))::date as last_month
  ), months as (
    select generate_series(b.last_month - make_interval(months => greatest(p_months, 1) - 1), b.last_month, interval '1 month')::date as month
      from bounds b
  ), origins (origin, cur) as (values ('IN', 'INR'::currency_code), ('CN', 'GBP'::currency_code))
  select m.month, o.origin,
         coalesce(sum(pl.qty), 0)::bigint,
         coalesce(sum(pl.goods_total), 0),
         coalesce(sum(pl.courier_total), 0)
    from months m cross join origins o
    left join (purchase_lines pl join vendors v on v.id = pl.vendor_id)
      on date_trunc('month', coalesce(pl.invoice_date, pl.period_month))::date = m.month
     and pl.category = 'stock' and v.country = o.origin and pl.currency = o.cur
   group by m.month, o.origin
   order by o.origin desc, m.month
$$;
grant execute on function dashboard_by_origin(integer, date) to authenticated;

-- ===== supabase/migrations/20261128000018_margins_fees.sql
-- MRG-10..MRG-18 (28 Nov 2026): Amazon FBM as its own row, eBay category fee, required costs, currency-check limits,
-- and the Shopify/OnBuy/Etsy fee settings named as each platform names them. Existing lines and figures are unchanged:
-- today's Amazon lines are FBA ('AMAZON'), and every new field starts empty or 0.

-- MRG-14: Amazon FBM is a sixth platform row (Amazon FBA stays 'AMAZON')
alter table margin_lines drop constraint margin_lines_channel_check;
alter table margin_lines add constraint margin_lines_channel_check check (channel in ('AMAZON', 'AMAZON_FBM', 'EBAY', 'SHOPIFY', 'ONBUY', 'ETSY'));

-- MRG-15: eBay category fee, % of the selling price, entered per product
alter table margin_lines add column category_fee_pct numeric(6, 3) check (category_fee_pct >= 0 and category_fee_pct < 100);

-- the view lists the new column (same columns as before, plus category_fee_pct at the end)
create or replace view v_margin_lines with (security_invoker = true) as
select m.id, m.margin_product_id, m.channel, m.company_code, m.listing_status, m.hidden,
       m.referral_pct, m.fba_fee, m.promo_per_unit, m.local_shipping, m.misc_expense, m.ad_pct, m.selling_price, m.tax_override_pct,
       p.product_id, p.name, p.asin, p.fnsku, p.owner, p.notes, p.product_cost, p.product_cost_currency, p.courier_cost, p.courier_currency,
       p.fx_rate, p.fx_rate_date, p.fx_source,
       c.name as company_name, c.default_vat_pct as company_vat_pct, coalesce(m.tax_override_pct, c.default_vat_pct) as effective_tax_pct,
       m.created_at, greatest(m.updated_at, p.updated_at) as updated_at,
       m.category_fee_pct
  from margin_lines m join margin_products p on p.id = m.margin_product_id join companies c on c.code = m.company_code;

-- MRG-11 and MRG-15: saving requires both costs and keeps the category fee
create or replace function save_margin_product(p jsonb) returns bigint
language plpgsql set search_path = public as $$
declare pid bigint := nullif(p ->> 'id', '')::bigint; x jsonb; n int;
begin
  if not is_admin() then raise exception 'Only an admin can change margins.' using errcode = 'P0001'; end if;
  -- MRG-11: both costs are required (0 is a valid courier cost)
  if nullif(p ->> 'product_cost', '') is null then raise exception 'Enter a product cost' using errcode = 'P0001'; end if;
  if nullif(p ->> 'courier_cost', '') is null then raise exception 'Enter a courier cost (enter 0 if there is none)' using errcode = 'P0001'; end if;
  if pid is null then
    insert into margin_products (product_id, name, asin, fnsku, owner, notes, product_cost, product_cost_currency, courier_cost,
                                 courier_currency, fx_rate, fx_source, fx_rate_date)
    values ((p ->> 'product_id')::bigint, p ->> 'name', p ->> 'asin', p ->> 'fnsku', p ->> 'owner', p ->> 'notes',
            coalesce((p ->> 'product_cost')::numeric, 0), coalesce(p ->> 'product_cost_currency', 'INR')::currency_code,
            coalesce((p ->> 'courier_cost')::numeric, 0), coalesce(p ->> 'courier_currency', 'INR')::currency_code,
            (p ->> 'fx_rate')::numeric, nullif(p ->> 'fx_source', ''), nullif(p ->> 'fx_rate_date', '')::date)
    returning id into pid;
  else
    update margin_products set product_id = (p ->> 'product_id')::bigint, name = p ->> 'name', asin = p ->> 'asin', fnsku = p ->> 'fnsku',
           owner = p ->> 'owner', notes = p ->> 'notes',
           product_cost = coalesce((p ->> 'product_cost')::numeric, 0), product_cost_currency = coalesce(p ->> 'product_cost_currency', 'INR')::currency_code,
           courier_cost = coalesce((p ->> 'courier_cost')::numeric, 0), courier_currency = coalesce(p ->> 'courier_currency', 'INR')::currency_code,
           fx_rate = (p ->> 'fx_rate')::numeric
     where id = pid;
    get diagnostics n = row_count;
    if n = 0 then raise exception 'Line not found.' using errcode = 'P0001'; end if;
  end if;
  for x in select * from jsonb_array_elements(coalesce(p -> 'platforms', '[]')) loop
    if exists (select 1 from margin_lines where margin_product_id = pid and channel = x ->> 'channel') then
      update margin_lines set company_code = x ->> 'company_code', selling_price = (x ->> 'selling_price')::numeric,
             tax_override_pct = (x ->> 'tax_override_pct')::numeric, hidden = coalesce((x ->> 'hidden')::boolean, false),
             listing_status = coalesce(x ->> 'listing_status', 'listed'),
             referral_pct = (x ->> 'referral_pct')::numeric, fba_fee = (x ->> 'fba_fee')::numeric, promo_per_unit = (x ->> 'promo_per_unit')::numeric,
             local_shipping = (x ->> 'local_shipping')::numeric, misc_expense = (x ->> 'misc_expense')::numeric, ad_pct = (x ->> 'ad_pct')::numeric,
             category_fee_pct = (x ->> 'category_fee_pct')::numeric
       where margin_product_id = pid and channel = x ->> 'channel'
         and (company_code, selling_price, tax_override_pct, hidden, listing_status, referral_pct, fba_fee, promo_per_unit,
              local_shipping, misc_expense, ad_pct, category_fee_pct)
             is distinct from
             (x ->> 'company_code', (x ->> 'selling_price')::numeric, (x ->> 'tax_override_pct')::numeric, coalesce((x ->> 'hidden')::boolean, false),
              coalesce(x ->> 'listing_status', 'listed'), (x ->> 'referral_pct')::numeric, (x ->> 'fba_fee')::numeric, (x ->> 'promo_per_unit')::numeric,
              (x ->> 'local_shipping')::numeric, (x ->> 'misc_expense')::numeric, (x ->> 'ad_pct')::numeric, (x ->> 'category_fee_pct')::numeric);
    elsif (x ->> 'selling_price') is not null or coalesce((x ->> 'hidden')::boolean, false) then
      insert into margin_lines (margin_product_id, channel, company_code, selling_price, tax_override_pct, hidden, listing_status,
                                referral_pct, fba_fee, promo_per_unit, local_shipping, misc_expense, ad_pct, category_fee_pct)
      values (pid, x ->> 'channel', x ->> 'company_code', (x ->> 'selling_price')::numeric, (x ->> 'tax_override_pct')::numeric,
              coalesce((x ->> 'hidden')::boolean, false), coalesce(x ->> 'listing_status', 'listed'),
              (x ->> 'referral_pct')::numeric, (x ->> 'fba_fee')::numeric, (x ->> 'promo_per_unit')::numeric,
              (x ->> 'local_shipping')::numeric, (x ->> 'misc_expense')::numeric, (x ->> 'ad_pct')::numeric, (x ->> 'category_fee_pct')::numeric);
    end if;
  end loop;
  return pid;
end $$;


-- MRG-11 AC5: the currency check limits
insert into settings (key, value, description) values
  ('margin_suspect_inr_below', '20', 'Margins: currency check: a ₹ product cost below this looks like £'),
  ('margin_suspect_gbp_above', '50', 'Margins: currency check: a £ product cost above this looks like ₹')
on conflict (key) do nothing;

-- MRG-16..18: the existing platform fee settings carry each platform's own names; Etsy's payment fee is 20p
update settings set description = 'Margins: Shopify selling fee (% of selling price)' where key = 'margin_shopify_fee_pct';
update settings set description = 'Margins: OnBuy sales fee (% of selling price)' where key = 'margin_onbuy_fee_pct';
update settings set description = 'Margins: Etsy transaction fee (% of selling price)' where key = 'margin_etsy_fee_pct';
update settings set description = 'Margins: Etsy payment fee (£ per order)' where key = 'margin_etsy_payment_fixed';
update settings set description = 'Margins: Etsy payment fee (% of selling price)' where key = 'margin_etsy_payment_pct';
update settings set value = '0.2' where key = 'margin_etsy_payment_fixed' and (value #>> '{}')::numeric = 0;

-- ===== supabase/migrations/20261128000019_no_duplicate_products.sql
-- PRD-08 and MRG-19 (28 Nov 2026): a new product (or margin line) that already exists is refused, naming the one that exists.
-- Same product = same name ignoring capitals, spaces and punctuation, or an ASIN/FNSKU already on another product.
-- Only new entries are checked: existing data (including any duplicates from the spreadsheet import) is left as it is,
-- and direct database loads (the importer) are not checked.

create function product_key(p_name text) returns text language sql immutable as $$
  select regexp_replace(lower(coalesce(p_name, '')), '[^a-z0-9]+', '', 'g')
$$;
create index products_key_idx on products (product_key(name));
create index margin_products_key_idx on margin_products (product_key(name));

-- products: the same name
create function product_no_duplicate() returns trigger
language plpgsql security definer set search_path = public as $$
declare hit text;
begin
  if is_system() then return new; end if;
  if tg_op = 'UPDATE' and product_key(new.name) = product_key(old.name) then return new; end if;
  select name into hit from products where product_key(name) = product_key(new.name) and id <> coalesce(new.id, -1) order by id limit 1;
  if hit is not null then raise exception 'Already created: %', hit using errcode = 'P0001'; end if;
  return new;
end $$;
create trigger a0_product_no_duplicate before insert or update of name on products for each row execute function product_no_duplicate();

-- listings: an FNSKU or ASIN that is already on another product (the same product listed by another company is fine)
create function listing_no_duplicate() returns trigger
language plpgsql security definer set search_path = public as $$
declare hit text; code text;
begin
  if is_system() then return new; end if;
  if nullif(btrim(coalesce(new.fnsku, '')), '') is not null
     and (tg_op = 'INSERT' or upper(coalesce(new.fnsku, '')) <> upper(coalesce(old.fnsku, ''))) then
    select p.name, upper(l.fnsku) into hit, code from listings l join products p on p.id = l.product_id
     where upper(l.fnsku) = upper(new.fnsku) and l.product_id <> new.product_id order by l.id limit 1;
    if hit is not null then raise exception 'Already created: % (FNSKU %)', hit, code using errcode = 'P0001'; end if;
  end if;
  if nullif(btrim(coalesce(new.asin, '')), '') is not null
     and (tg_op = 'INSERT' or upper(coalesce(new.asin, '')) <> upper(coalesce(old.asin, ''))) then
    select p.name, upper(l.asin) into hit, code from listings l join products p on p.id = l.product_id
     where upper(l.asin) = upper(new.asin) and l.product_id <> new.product_id order by l.id limit 1;
    if hit is not null then raise exception 'Already created: % (ASIN %)', hit, code using errcode = 'P0001'; end if;
  end if;
  return new;
end $$;
create trigger a0_listing_no_duplicate before insert or update of fnsku, asin on listings for each row execute function listing_no_duplicate();

-- margin lines: the same name, ASIN or FNSKU as another margin line
create function margin_product_no_duplicate() returns trigger
language plpgsql security definer set search_path = public as $$
declare hit text; code text;
begin
  if is_system() then return new; end if;
  if tg_op = 'INSERT' or product_key(new.name) <> product_key(old.name) then
    select name into hit from margin_products where product_key(name) = product_key(new.name) and id <> coalesce(new.id, -1) order by id limit 1;
    if hit is not null then raise exception 'Already created: %', hit using errcode = 'P0001'; end if;
  end if;
  if nullif(btrim(coalesce(new.asin, '')), '') is not null and (tg_op = 'INSERT' or upper(coalesce(new.asin, '')) <> upper(coalesce(old.asin, ''))) then
    select name, upper(asin) into hit, code from margin_products where upper(asin) = upper(new.asin) and id <> coalesce(new.id, -1) order by id limit 1;
    if hit is not null then raise exception 'Already created: % (ASIN %)', hit, code using errcode = 'P0001'; end if;
  end if;
  if nullif(btrim(coalesce(new.fnsku, '')), '') is not null and (tg_op = 'INSERT' or upper(coalesce(new.fnsku, '')) <> upper(coalesce(old.fnsku, ''))) then
    select name, upper(fnsku) into hit, code from margin_products where upper(fnsku) = upper(new.fnsku) and id <> coalesce(new.id, -1) order by id limit 1;
    if hit is not null then raise exception 'Already created: % (FNSKU %)', hit, code using errcode = 'P0001'; end if;
  end if;
  return new;
end $$;
create trigger a0_margin_product_no_duplicate before insert or update of name, asin, fnsku on margin_products
  for each row execute function margin_product_no_duplicate();

-- ===== supabase/migrations/20261128000020_cae_code.sql
-- MRG-21 (28 Nov 2026): every margin line (catalogue item) has a Caemora product identifier: CAE + its number, e.g. CAE0001.
-- Assigned automatically in order when a line is created; required; can't be changed or typed in; numbers are never reused.
-- Existing lines are numbered in the order they were created.

create sequence margin_cae_seq;
create function cae_code(p_n bigint) returns text language sql immutable as $$
  select 'CAE' || case when p_n < 10000 then lpad(p_n::text, 4, '0') else p_n::text end
$$;

alter table margin_products add column cae_code text;
-- numbered quietly: no "updated" time, rate re-check or audit entry for existing lines
alter table margin_products disable trigger user;
update margin_products m set cae_code = cae_code(o.n)
  from (select id, row_number() over (order by created_at, id) as n from margin_products) o where o.id = m.id;
alter table margin_products enable trigger user;
select setval('margin_cae_seq', greatest((select count(*) from margin_products), 1), (select count(*) > 0 from margin_products));
alter table margin_products alter column cae_code set not null, add constraint margin_products_cae_code_key unique (cae_code);

create function margin_cae_code() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.cae_code := cae_code(nextval('margin_cae_seq'));      -- whatever was passed in
  elsif new.cae_code is distinct from old.cae_code then
    raise exception 'The Caemora product ID cannot be changed.' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger a_margin_cae_code before insert or update of cae_code on margin_products for each row execute function margin_cae_code();

-- the list view carries it (same columns as before, plus cae_code at the end)
create or replace view v_margin_lines with (security_invoker = true) as
select m.id, m.margin_product_id, m.channel, m.company_code, m.listing_status, m.hidden,
       m.referral_pct, m.fba_fee, m.promo_per_unit, m.local_shipping, m.misc_expense, m.ad_pct, m.selling_price, m.tax_override_pct,
       p.product_id, p.name, p.asin, p.fnsku, p.owner, p.notes, p.product_cost, p.product_cost_currency, p.courier_cost, p.courier_currency,
       p.fx_rate, p.fx_rate_date, p.fx_source,
       c.name as company_name, c.default_vat_pct as company_vat_pct, coalesce(m.tax_override_pct, c.default_vat_pct) as effective_tax_pct,
       m.created_at, greatest(m.updated_at, p.updated_at) as updated_at,
       m.category_fee_pct, p.cae_code
  from margin_lines m join margin_products p on p.id = m.margin_product_id join companies c on c.code = m.company_code;

-- ===== supabase/migrations/20261128000021_losses.sql
-- LOS-01..LOS-04 (28 Nov 2026): record losses so they can be accounted for every month.
-- Net loss (£) = goods at landed cost + refund paid to the buyer − anything recovered (e.g. an Amazon reimbursement).
-- Admins and the India team record and correct losses at any time (settled months included: they are often found late);
-- viewers read; only an admin deletes. Every change is in the Audit log.

create table losses (
  id              bigint generated always as identity primary key,
  occurred_on     date not null,
  month           date not null,
  type            text not null check (type in ('lost_in_transit', 'damaged_return', 'refunded_no_return', 'expired')),
  company_code    text not null references companies (code),
  platform        text check (platform in ('AMAZON', 'AMAZON_FBM', 'EBAY', 'SHOPIFY', 'ONBUY', 'ETSY', 'TIKTOK', 'OTHER')),
  product_id      bigint not null references products (id),
  qty             integer not null check (qty > 0),
  unit_cost_gbp   numeric(12, 4) not null check (unit_cost_gbp >= 0),     -- landed cost per unit, offered from the purchase
  goods_gbp       numeric(14, 2) generated always as (round(qty * unit_cost_gbp, 2)) stored,
  refund_gbp      numeric(12, 2) not null default 0 check (refund_gbp >= 0),
  recovered_gbp   numeric(12, 2) not null default 0 check (recovered_gbp >= 0),
  net_loss_gbp    numeric(14, 2) generated always as (round(qty * unit_cost_gbp, 2) + refund_gbp - recovered_gbp) stored,
  shipment_id     bigint references shipments (id) on delete set null,
  reference       text,            -- order ID, case ID, tracking number…
  notes           text,
  created_by      uuid references auth.users (id) default auth.uid(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index losses_month_idx on losses (month, company_code);
create index losses_shipment_idx on losses (shipment_id);

create function losses_month() returns trigger language plpgsql as $$
begin
  new.month := date_trunc('month', new.occurred_on)::date;
  new.updated_at := now();
  return new;
end $$;
create trigger b_losses_month before insert or update on losses for each row execute function losses_month();

alter table losses enable row level security;
create policy read_all on losses for select to authenticated using (is_active_user());
create policy staff_insert on losses for insert to authenticated with check (is_staff());
create policy staff_update on losses for update to authenticated using (is_staff()) with check (is_staff());
create policy admin_delete on losses for delete to authenticated using (is_admin());
grant select, insert, update, delete on losses to authenticated;
create trigger z_audit after insert or update or delete on losses for each row execute function write_audit();

create view v_losses with (security_invoker = true) as
select l.*, p.name as product_name, c.name as company_name, person_name(l.created_by) as recorded_by_name,
       s.amazon_shipment_id, s.box_no
  from losses l join products p on p.id = l.product_id join companies c on c.code = l.company_code
  left join shipments s on s.id = l.shipment_id;
grant select on v_losses to authenticated;

-- LOS-02: landed cost per unit in £ of a product's latest purchase (₹ converted at that line's rate)
create function landed_cost_gbp(p_product bigint) returns numeric
language sql stable security invoker set search_path = public as $$
  select round(landed_per_unit_gbp, 4) from v_purchase_lines
   where product_id = p_product and landed_per_unit_gbp is not null and unit_price is not null
   order by period_month desc, id desc limit 1
$$;

-- LOS-04: what was in a lost box, with each line's own landed cost per unit, and how many units are already recorded as lost
create function loss_lines_for_shipment(p_shipment bigint)
returns table (product_id bigint, product_name text, company_code text, qty integer, unit_cost_gbp numeric, already_recorded integer)
language sql stable security invoker set search_path = public as $$
  select pl.product_id, pl.product_name, pl.company_code, i.qty, round(pl.landed_per_unit_gbp, 4),
         coalesce((select sum(l.qty) from losses l where l.shipment_id = p_shipment and l.product_id = pl.product_id), 0)::integer
    from shipment_items i join v_purchase_lines pl on pl.id = i.purchase_line_id
   where i.shipment_id = p_shipment
   order by pl.product_name
$$;
grant execute on function landed_cost_gbp(bigint), loss_lines_for_shipment(bigint) to authenticated;

